INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('immortal-the-usa', 'NES', 'Immortal, The (USA)', '1990', 'Action', 'Electronic Arts', '1', 'Action adventure', 'Isometric action / Puzzle.', 'Descend into the labyrinth to rescue your mentor, Mordamir.', 'A dark, atmospheric RPG known for its brutal death animations.', 'Featuring complex puzzles and real-time combat, it stands out for its mature tone, high-quality graphics, and isometric exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('impossible-mission-ii-usa-unl', 'NES', 'Impossible Mission II (USA) (Unl)', 'Unlicensed', 'Action', 'Epyx', '1', 'Action platformer', 'Action / Platformer.', 'Infiltrate Elvin''s towers and recover the musical passcodes.', 'An unlicensed port of the classic Epyx computer adventure.', 'Players must search furniture and hack terminals while avoiding security robots in a race against the clock to stop a nuclear launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incantation-asia-unl-famicom', 'NES', 'Incantation (Asia) (Unl) (Famicom)', 'Unlicensed', 'Action', 'Unknown', '1', 'Action shooter', 'Side-scrolling action.', 'Use your magic wand to defeat monsters in a fantasy realm.', 'An unlicensed Famicom action title by Sachen.', 'Players control a young wizard through various levels, collecting power-ups and fighting bosses in a style similar to other 8-bit fantasy platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-europe', 'NES', 'Incredible Crash Dummies, The (Europe)', '1993', 'Action', 'Gray Matter', '1', 'Action platformer', 'Action / Mini-games.', 'Complete various safety tests to prove you are the best dummy.', 'A colorful game based on the popular safety-themed toy line.', 'It features varied levels like car crashes, tire-rolling races, and platforming, all emphasizing the "destruction" gimmick of the characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa', 'NES', 'Incredible Crash Dummies, The (USA)', '1993', 'Action', 'Gray Matter', '1', 'Action platformer', 'Action / Mini-games.', 'Complete various safety tests to prove you are the best dummy.', 'A colorful game based on the popular safety-themed toy line.', 'It features varied levels like car crashes, tire-rolling races, and platforming, all emphasizing the "destruction" gimmick of the characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-europe', 'NES', 'Indiana Jones and the Last Crusade (Europe)', '1989', 'Action', 'Taito', '1', 'Action platformer', 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'The European version of the cinematic movie adaptation.', 'Following the film''s plot, Indy travels through Venice and castles, using his whip to swing over pits and fight enemies in a balanced platforming quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-usa-taito', 'NES', 'Indiana Jones and the Last Crusade (USA) (Taito)', '1989', 'Action', 'Taito', '1', 'Action platformer', 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'A polished Taito-developed adventure with great visuals.', 'This version is praised for its detailed sprites and faithful locations. It features multiple paths and puzzles that capture the adventurous spirit of the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-usa-ubi-soft', 'NES', 'Indiana Jones and the Last Crusade (USA) (UBI Soft)', '1988', 'Action', 'Ubi Soft', '1', 'Action platformer', 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'A different interpretation of the film by UBI Soft.', 'Featuring a focus on combat and exploration, this version offers a distinct level layout and artistic style compared to the Taito release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-temple-of-doom-usa', 'NES', 'Indiana Jones and the Temple of Doom (USA)', '1988', 'Action', 'Taito', '1', 'Action platformer', 'Side-scrolling action.', 'Rescue the village children and recover the Sankara Stones.', 'An action-heavy adaptation of the second Indiana Jones film.', 'Players explore the dark mines of Mola Ram, using the whip to fight cultists and riding mine carts in fast-paced, hazardous sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-temple-of-doom-usa-rev-a', 'NES', 'Indiana Jones and the Temple of Doom (USA) (Rev A)', '1988', 'Action', 'Ubi Soft', '1', 'Action platformer', 'Side-scrolling action.', 'Rescue the children and recover the stones with bug fixes.', 'A revised version of the Mindscape Indiana Jones game.', 'This update addresses minor level design issues and improves the physics of the whip, making the mining levels slightly more manageable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-temple-of-doom-usa-unl', 'NES', 'Indiana Jones and the Temple of Doom (USA) (Unl)', '1988', 'Action', 'Taito', '1', 'Action platformer', 'Side-scrolling action.', 'Rescue the village children and recover the Sankara Stones.', 'The unlicensed black-cartridge version released by Tengen.', 'Identical in gameplay to the licensed release but sold outside Nintendo''s control, featuring the same arcade-style action and mine-cart levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indora-no-hikari-japan', 'NES', 'Indora no Hikari (Japan)', 'Unlicensed', 'Action', 'Unknown', '1', 'Action platformer', 'Turn-based RPG.', 'Travel through fantasy worlds to restore light to the land.', 'A classic Famicom RPG featuring party-based combat.', 'Known for its colorful graphics and traditional mechanics, players explore towns and dungeons, talking to NPCs to unravel a grand mythological story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('infiltrator-usa', 'NES', 'Infiltrator (USA)', '1991', 'Action', 'Kemco', '1', 'Action adventure', 'Flight sim / Action.', 'Fly into enemy territory and complete stealth missions on foot.', 'A hybrid game blending helicopter simulation with top-down action.', 'Players must master the cockpit controls of the "Gizmo" helicopter before landing to perform sabotage missions in a high-stakes 8-bit spy thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('insector-x-japan', 'NES', 'Insector X (Japan)', '1990', 'Shooter', 'Irem', '1', 'Vertical shooter', 'Horizontal shoot ''em up.', 'Fight through the insect kingdom to defeat the mechanical Queen.', 'A quirky shooter featuring an insect-sized hero in a big world.', 'Players use diverse power-ups to shoot through swarms of bees and beetles, featuring impressive parallax scrolling and large, bug-themed bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-cricket-australia', 'NES', 'International Cricket (Australia)', '1991', 'Sports', 'Melbourne House', '2', 'Cricket sports', 'Sports / Cricket.', 'Win the world series in this professional cricket simulation.', 'A rare and detailed cricket game released specifically for Australia.', 'It offers comprehensive control over batting, bowling, and fielding, featuring realistic rules and multiple international teams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-cricket-australia-beta', 'NES', 'International Cricket (Australia) (Beta)', '1991', 'Sports', 'Melbourne House', '2', 'Cricket sports', 'Sports / Cricket.', 'Win the world series in this early development version.', 'A prototype of the Australian cricket simulator.', 'This version shows early menus and slightly different physics for the ball, providing a look at how the 8-bit cricket logic was refined.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-tank---the-invasion-of-normandy-europe', 'NES', 'Iron Tank - The Invasion of Normandy (Europe)', '1988', 'Action', 'SNK', '2', 'Tank shooter', 'Top-down shooter.', 'Drive through Normandy and destroy the Nazi secret weapon.', 'An intense SNK tank shooter with branching paths.', 'Known for its high-quality soundtrack and tactical depth, players can choose different routes and upgrade their tank''s weapons to survive the war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-tank---the-invasion-of-normandy-usa', 'NES', 'Iron Tank - The Invasion of Normandy (USA)', '1988', 'Action', 'SNK', '2', 'Tank shooter', 'Top-down shooter.', 'Drive through Normandy and destroy the Nazi secret weapon.', 'An intense SNK tank shooter with branching paths.', 'Known for its high-quality soundtrack and tactical depth, players can choose different routes and upgrade their tank''s weapons to survive the war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ironsword---wizards-&-warriors-ii-europe', 'NES', 'Ironsword - Wizards & Warriors II (Europe)', '1989', 'Action', 'Rare', '1', 'Action adventure', 'Action platformer.', 'Collect the elements of the sword to defeat the wizard Malkil.', 'The high-fantasy sequel to "Wizards & Warriors."', 'Featuring Fabio on the cover, this game expands on the original with massive levels and more complex magic systems, all with a distinct Acclaim style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ironsword---wizards-&-warriors-ii-usa', 'NES', 'Ironsword - Wizards & Warriors II (USA)', '1989', 'Action', 'Rare', '1', 'Action adventure', 'Action platformer.', 'Collect the elements of the sword to defeat the wizard Malkil.', 'The high-fantasy sequel to "Wizards & Warriors."', 'Featuring Fabio on the cover, this game expands on the original with massive levels and more complex magic systems, all with a distinct Acclaim style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isaki-shuugorou-no-keiba-hisshou-gaku-japan', 'NES', 'Isaki Shuugorou no Keiba Hisshou Gaku (Japan)', '1990', 'Action', 'KID', '1', 'Action platformer', 'Sports / Horse Racing.', 'Place bets and manage horses to win at the digital racetrack.', 'A detailed horse racing simulation with a focus on statistics.', 'Based on the expertise of a famous Japanese racing commentator, it offers deep menus for analyzing horse data and betting strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ishin-no-arashi-japan', 'NES', 'Ishin no Arashi (Japan)', '1990', 'Action', 'KID', '1', 'Action platformer', 'Turn-based strategy.', 'Navigate the political unrest of the Meiji Restoration.', 'A complex Koei historical simulation set in late 19th-century Japan.', 'Players take on the role of historical figures, using diplomacy and military force to influence the fate of the nation during a period of massive change.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isolated-warrior-europe', 'NES', 'Isolated Warrior (Europe)', '1991', 'Strategy', 'ASCII', '1', 'Economic strategy', 'Isometric shooter.', 'Fight through an alien-invaded world to save humanity.', 'A fast-paced shooter with a unique isometric perspective.', 'Known for its pseudo-3D graphics, it combines running and jumping with intense shooting, featuring great music and a futuristic "Mad Max" aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isolated-warrior-usa', 'NES', 'Isolated Warrior (USA)', '1989', 'Racing', 'Rare', '2', 'Off-road racing', 'Isometric shooter.', 'Fight through an alien-invaded world to save humanity.', 'A fast-paced shooter with a unique isometric perspective.', 'Known for its pseudo-3D graphics, it combines running and jumping with intense shooting, featuring great music and a futuristic "Mad Max" aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itadaki-street---watashi-no-mise-ni-yottette-japan', 'NES', 'Itadaki Street - Watashi no Mise ni Yottette (Japan)', '1989', 'Racing', 'Rare', '2', 'Off-road racing', 'Board game / Strategy.', 'Buy properties and stocks to become the wealthiest player.', 'The first game in the famous "Fortune Street" digital board game series.', 'Created by Yuji Horii, it blends Monopoly-style property buying with a complex stock market system, making it a deep and addictive multiplayer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ivan-ironman-stewarts-super-off-road-europe', 'NES', 'Ivan ''Ironman'' Stewart''s Super Off-Road (Europe)', '1993', 'Sports', 'Konami', '2', 'Soccer sports', 'Isometric racing.', 'Race on dirt tracks to earn money and upgrade your truck.', 'A high-speed arcade racer featuring Ivan Stewart''s endorsement.', 'Players compete on bumpy, loop-based tracks, using nitrous boosts to gain an edge. The goal is to finish in the top positions to fund better tires and acceleration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ivan-ironman-stewarts-super-off-road-usa', 'NES', 'Ivan ''Ironman'' Stewart''s Super Off-Road (USA)', '1994', 'Sports', 'Konami', '2', 'Soccer sports', 'Isometric racing.', 'Race on dirt tracks to earn money and upgrade your truck.', 'A high-speed arcade racer featuring Ivan Stewart''s endorsement.', 'Players compete on bumpy, loop-based tracks, using nitrous boosts to gain an edge. The goal is to finish in the top positions to fund better tires and acceleration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-fighting-soccer---the-king-of-ace-strikers-japan', 'NES', 'J.League Fighting Soccer - The King of Ace Strikers (Japan)', '1994', 'Sports', 'Konami', '2', 'Soccer sports', 'Sports / Soccer.', 'Win the Japanese J.League championship with your chosen team.', 'A fast-paced soccer sim featuring real Japanese clubs and players.', 'It offers a more arcade-like approach to football, with smooth scrolling and simplified controls that focus on high-scoring matches and league progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-winning-goal-japan', 'NES', 'J.League Winning Goal (Japan)', '1988', 'Sports', 'Kemco', '1', 'Golf simulation', 'Sports / Soccer.', 'Lead your club to the top of the Japanese pro league.', 'A polished late-era Famicom soccer game with detailed stats.', 'Featuring better graphics than its predecessors, it includes a management mode and refined pitch perspectives for a more professional 8-bit sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-winning-goal-japan-en-by-stardust-crusaders-v10', 'NES', 'J.League Winning Goal (Japan) [En by Stardust Crusaders v1.0]', '1988', 'Sports', 'Kemco', '1', 'Golf simulation', 'Sports / Soccer.', 'Lead your club to the top with fully translated menus and stats.', 'The English fan translation of the advanced J.League sim.', 'This version allows Western players to fully understand the strategic management menus and player statistics of this Japanese-exclusive soccer title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-greatest-18-holes-of-major-championship-golf-europe', 'NES', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf (Europe)', '1988', 'Action', 'Konami', '2', 'Run and gun', 'Sports / Golf.', 'Play through the world''s most famous holes with low scores.', 'A technical golf simulation endorsed by the legendary Jack Nicklaus.', 'This game focuses on realism, requiring players to account for wind and terrain on meticulously recreated 8-bit versions of major championship courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-greatest-18-holes-of-major-championship-golf-usa', 'NES', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf (USA)', '1987', 'Action', 'Hudson Soft', '1', 'Action platformer', 'Sports / Golf.', 'Play through the world''s most famous holes with low scores.', 'A technical golf simulation endorsed by the legendary Jack Nicklaus.', 'This game focuses on realism, requiring players to account for wind and terrain on meticulously recreated 8-bit versions of major championship courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackal-usa', 'NES', 'Jackal (USA)', 'Unlicensed', 'Action', 'Unknown', '1', 'Action platformer', 'Top-down run and gun.', 'Infiltrate enemy territory with a jeep to rescue POWs.', 'One of the most beloved and intense co-op shooters on the NES.', 'As part of an elite squad, players drive through enemy bases, upgrading their grenades to missiles to destroy tanks and rescue soldiers behind enemy lines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chan-japan', 'NES', 'Jackie Chan (Japan)', '1987', 'Action', 'Hudson Soft', '1', 'Action platformer', 'Side-scrolling action.', 'Fight through diverse stages to rescue your twin sister.', 'A vibrant and highly animated martial arts platformer.', 'Known for its charming art style and smooth combat, Jackie uses punches, kicks, and special "moves" to defeat bosses across a mystical 8-bit China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chan-stage-select-hack', 'NES', 'Jackie Chan stage select hack', 'Unlicensed', 'Action', 'Unknown', '1', 'Action platformer', 'Side-scrolling action.', 'Play any level of the Jackie Chan adventure from the start.', 'A modified version allowing for immediate level selection.', 'This hack is perfect for players who want to jump straight into their favorite boss fights or test their skills on the more difficult late-game stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chans-action-kung-fu-europe', 'NES', 'Jackie Chan''s Action Kung Fu (Europe)', '1988', 'Action', 'Jaleco', '1', 'Action adventure', 'Side-scrolling action.', 'Fight through diverse stages to rescue your twin sister.', 'A vibrant and highly animated martial arts platformer.', 'Known for its charming art style and smooth combat, Jackie uses punches, kicks, and special "moves" to defeat bosses across a mystical 8-bit China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chans-action-kung-fu-usa', 'NES', 'Jackie Chan''s Action Kung Fu (USA)', '1987', 'Action', 'Jaleco', '1', 'Action platformer', 'Side-scrolling action.', 'Fight through diverse stages to rescue your twin sister.', 'A vibrant and highly animated martial arts platformer.', 'Known for its charming art style and smooth combat, Jackie uses punches, kicks, and special "moves" to defeat bosses across a mystical 8-bit China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chans-hulk-smash-usa', 'NES', 'Jackie Chan''s Hulk Smash (USA)', '1987', 'Action', 'Jaleco', '1', 'Action platformer', 'Side-scrolling action (Hack).', 'Play as a green-colored Jackie with increased power.', 'A fun character-modifier hack for the Action Kung Fu engine.', 'This version modifies Jackie''s sprites and damage output, giving a "superhero" feel to the traditional martial arts gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jajamaru-gekimaden---maboroshi-no-kinmajou-japan', 'NES', 'Jajamaru Gekimaden - Maboroshi no Kinmajou (Japan)', '1991', 'Action', 'Vic Tokai', '1', 'Action platformer', 'Action RPG.', 'Journey to the Devil''s Castle to defeat the Phantom Lord.', 'A top-down action adventure from the Ninja Jajamaru-kun series.', 'It blends village exploration with real-time combat in dungeons, featuring a wide variety of items and magic to help Jajamaru on his quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jajamaru-ninpou-chou-japan', 'NES', 'Jajamaru Ninpou Chou (Japan)', '1991', 'Action', 'Vic Tokai', '1', 'Action platformer', 'Turn-based RPG.', 'Lead Jajamaru and Sakura on a quest to save the princess.', 'The series'' first foray into traditional turn-based role-playing.', 'Unlike the action titles, this game focuses on story progression, character leveling, and strategic battles against mythological Japanese monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jajamaru-no-daibouken-japan', 'NES', 'Jajamaru no Daibouken (Japan)', '1988', 'Board Game', 'Namco', '2', 'Mahjong board game', 'Side-scrolling action.', 'Defeat the catfish pirate and his army of Yokai.', 'A classic horizontal platformer starring the red ninja Jajamaru.', 'It features fast-paced combat where Jajamaru throws shurikens and rides a giant frog to clear swarms of enemies across various historical Japanese levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-jr-europe', 'NES', 'James Bond Jr (Europe)', '1988', 'Adventure', 'Konami', '1', 'Narrative adventure', 'Side-scrolling action.', 'Stop the evil S.C.U.M. organization as Bond''s talented nephew.', 'A gadget-filled action game based on the 90s animated series.', 'Players must navigate levels filled with traps, using specialized equipment like jetpacks and grenades to complete missions and dismantle global threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-jr-usa', 'NES', 'James Bond Jr (USA)', '1987', 'Action', 'Westwood Associates', '1', 'Action adventure', 'Side-scrolling action.', 'Stop the evil S.C.U.M. organization as Bond''s talented nephew.', 'A gadget-filled action game based on the 90s animated series.', 'Players must navigate levels filled with traps, using specialized equipment like jetpacks and grenades to complete missions and dismantle global threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jangou-japan', 'NES', 'Jangou (Japan)', '1991', 'Quiz', 'GameTek', '3', 'TV quiz game', 'Mahjong / Strategy.', 'Defeat various opponents in the traditional game of Mahjong.', 'A straightforward and polished Mahjong simulation for the Famicom.', 'It focuses on the pure rules of the game, offering a challenging AI for players looking to practice their 8-bit tile-matching and strategic gambling skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jarinko-chie---bakudan-musume-no-shiawase-sagashi-japan', 'NES', 'Jarinko Chie - Bakudan Musume no Shiawase Sagashi (Japan)', '1988', 'Action', 'Taito', '1', 'Action Adventure', 'Adventure / Visual Novel.', 'Follow the life of Chie in a series of comedic urban adventures.', 'An adventure game based on the popular manga and anime series.', 'Featuring menu-driven gameplay, players help the young and energetic Chie manage her father''s shop and deal with the eccentric characters of Osaka.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jaws-usa', 'NES', 'Jaws (USA)', '1987', 'Action', 'LJN', '1', 'Action', 'Action / Hunting.', 'Hunt down the great white shark across the ocean.', 'An LJN-published game where you upgrade your ship to kill Jaws.', 'Players sail a map, engaging in mini-games to collect shells and power-ups, culminating in a first-person harpoon battle against the legendary shark.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa', 'NES', 'Jeopardy! (USA)', '1988', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Answer questions in the form of a question to win money.', 'An 8-bit adaptation of the world-famous television game show.', 'It features a large database of questions across various categories, challenging players to "buzz in" first and manage their winnings for Final Jeopardy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa-rev-a', 'NES', 'Jeopardy! (USA) (Rev A)', '1988', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Answer questions in the form of a question to win money.', 'A revised version with improved logic for text input.', 'This update polishes the answer-recognition system, making the game more forgiving with spelling and improving the overall flow of the trivia rounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-25th-anniversary-edition-usa', 'NES', 'Jeopardy! 25th Anniversary Edition (USA)', '1990', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Win the ultimate trivia tournament in this anniversary special.', 'An updated version featuring thousands of new questions.', 'Celebrating 25 years of the show, this edition includes more difficult categories and a refined presentation of the classic Jeopardy! experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-junior-edition-usa', 'NES', 'Jeopardy! Junior Edition (USA)', '1989', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Win money in this youth-oriented version of the game show.', 'A version of Jeopardy! featuring easier questions for younger players.', 'While the gameplay remains the same, the categories focus on pop culture, cartoons, and basic school subjects suited for a younger audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jesus---kyoufu-no-bio-monster-japan', 'NES', 'Jesus - Kyoufu no Bio Monster (Japan)', '1987', 'Horror RPG', 'Enix', '1', 'Horror RPG', 'Adventure / Sci-Fi.', 'Investigate a biological threat on a space station near Halley''s Comet.', 'A cinematic sci-fi adventure with a strong horror atmosphere.', 'Known for its incredible music and detailed cutscenes, players navigate menus to solve puzzles and uncover the mystery of the "Jesus" monster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jesus---kyoufu-no-bio-monster-japan-en-by-niahak-v11', 'NES', 'Jesus - Kyoufu no Bio Monster (Japan) [En by Niahak v1.1]', '1987', 'Horror RPG', 'Enix', '1', 'Horror RPG', 'Adventure / Sci-Fi.', 'Solve the space station mystery with full English translation.', 'The English fan translation of the cult classic sci-fi adventure.', 'This version is vital for Western fans to experience the tension-filled story and complex puzzles of this unique Famicom thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jetsons-the---cogswells-caper!-europe', 'NES', 'Jetsons, The - Cogswell''s Caper! (Europe)', '1992', 'Action Platformer', 'Taito', '1', 'Action Platformer', 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'A late-release high-quality platformer by Taito.', 'George uses gadgets and switches between gravity-defying shoes to navigate futuristic levels, featuring the whole Jetson family and great 8-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jetsons-the---cogswells-caper!-japan', 'NES', 'Jetsons, The - Cogswell''s Caper! (Japan)', '1992', 'Action Platformer', 'Taito', '1', 'Action Platformer', 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'The Japanese version of the polished Taito platformer.', 'It maintains the excellent level design and music, proving to be one of the best examples of a cartoon-to-game adaptation on the Famicom hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jetsons-the---cogswells-caper!-usa', 'NES', 'Jetsons, The - Cogswell''s Caper! (USA)', '1992', 'Action Platformer', 'Taito', '1', 'Action Platformer', 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'A late-release high-quality platformer by Taito.', 'George uses gadgets and switches between gravity-defying shoes to navigate futuristic levels, featuring the whole Jetson family and great 8-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigoku-gokuraku-maru-japan', 'NES', 'Jigoku Gokuraku Maru (Japan)', '1988', 'Action', 'Sunsoft', '1', 'Action', 'Side-scrolling action.', 'Battle demons across Tokyo to stop a supernatural threat.', 'Known in the West as "Kabuki Quantum Fighter."', 'Players control a digital version of a Kabuki actor who uses his long hair as a whip. It features a cool cyberpunk aesthetic and very tight platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikuu-yuuden---debias-japan', 'NES', 'Jikuu Yuuden - Debias (Japan)', '1988', 'Action RPG', 'Namco', '1', 'Action RPG', 'Side-scrolling action platformer with shooting and jumping mechanics', 'Defeat enemies and bosses to progress through stages', 'A futuristic action platformer with intense combat', 'Jikuu Yuuden - Debias is a sci-fi side-scrolling action game where players control a cybernetic warrior fighting through hostile environments. The gameplay focuses on precise jumping, fast shooting, and defeating powerful bosses while uncovering a dark futuristic storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-tennis-europe', 'NES', 'Jimmy Connors Tennis (Europe)', '1988', 'Sports', 'NMS Software', '2', 'Tennis', 'Sports tennis simulation with arcade-style controls', 'Win matches by scoring more points than the opponent', 'A fast-paced tennis game featuring real player branding', 'Jimmy Connors Tennis offers an accessible yet competitive tennis experience on NES. Players compete in singles matches using responsive controls, timing-based shots, and strategic positioning inspired by arcade sports games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-tennis-usa', 'NES', 'Jimmy Connors Tennis (USA)', '1988', 'Sports', 'NMS Software', '2', 'Tennis', 'Sports tennis simulation with arcade-style controls', 'Win matches by scoring more points than the opponent', 'A fast-paced tennis game featuring real player branding', 'Jimmy Connors Tennis delivers classic NES sports gameplay with easy-to-learn mechanics. Players face off in tennis matches emphasizing reflexes, court coverage, and simple but satisfying competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jj---tobidase-daisakusen-part-2-japan', 'NES', 'JJ - Tobidase Daisakusen Part 2 (Japan)', '1991', 'Action', 'NCS', '1', 'Action Platformer', 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'An isometric action game focused on precision jumps', 'JJ - Tobidase Daisakusen Part 2 challenges players with angled perspectives and demanding platforming. The game emphasizes spatial awareness, enemy avoidance, and careful timing across multiple obstacle-filled stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jj---tobidase-daisakusen-part-2-japan-en-by-dvd-v10-~jj---jump-out!-the-epic-war---part-ii', 'NES', 'JJ - Tobidase Daisakusen Part 2 (Japan) [En by DvD v1.0] (~JJ - Jump Out! The Epic War - Part II)', '1991', 'Action', 'NCS', '1', 'Action Platformer', 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'An isometric action game focused on precision jumps', 'This translated version of JJ - Tobidase Daisakusen Part 2 allows English-speaking players to enjoy its unique 3D-like platforming. The game rewards patience, memorization, and mastery of tricky jumps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jj---tobidase-daisakusen-part-2-japan-en-by-dvd-v10-~jj---the-3-d-battles-of-worldrunner---part-ii', 'NES', 'JJ - Tobidase Daisakusen Part 2 (Japan) [En by DvD v1.0] (~JJ - The 3-D Battles of WorldRunner - Part II)', '1991', 'Action', 'NCS', '1', 'Action Platformer', 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'A challenging sequel to an early 3D-style action game', 'Known in English as The 3-D Battles of WorldRunner Part II, this game expands on its predecessor with tougher levels, faster pacing, and demanding precision-based gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac---caveman-ninja-europe', 'NES', 'Joe & Mac - Caveman Ninja (Europe)', '1991', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling platformer with combat and cooperative play', 'Defeat enemies and rescue caveman allies', 'A colorful prehistoric action platformer', 'Joe & Mac - Caveman Ninja is a vibrant platform game where players battle dinosaurs and rival tribes using clubs and projectiles. The game supports cooperative play and is known for its humor and fast-paced action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-usa', 'NES', 'Joe & Mac (USA)', '1991', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling platformer with combat and cooperative play', 'Defeat enemies and rescue caveman allies', 'A colorful prehistoric action platformer', 'Joe & Mac brings classic arcade-style platforming to NES, combining tight controls, enemy-filled stages, and charming visuals set in a comedic prehistoric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-elways-quarterback-usa', 'NES', 'John Elway''s Quarterback (USA)', '1988', 'Sports', 'Rare', '2', 'Football', 'American football sports simulation with play selection', 'Score touchdowns and win football games', 'A strategic football game starring an NFL quarterback', 'John Elway''s Quarterback focuses on play-calling and execution rather than arcade action. Players choose offensive plays and attempt to outscore opponents using timing, positioning, and football strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jongbou-japan', 'NES', 'Jongbou (Japan)', '1988', 'Board Game', 'ASCII', '2', 'Board Game', 'Traditional mahjong board game simulation', 'Win matches by forming winning tile hands', 'A digital version of classic Japanese mahjong', 'Jongbou is a faithful NES adaptation of Japanese mahjong. The game emphasizes rules knowledge, strategic tile management, and careful decision-making rather than action-based gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jordan-vs-bird---one-on-one-usa', 'NES', 'Jordan vs Bird - One On One (USA)', '1983', 'Sports', 'Electronic Arts', '2', 'Sports', 'One-on-one basketball sports game', 'Outscore the opponent in direct matches', 'A basketball game featuring legendary players', 'Jordan vs Bird recreates iconic basketball matchups in a fast-paced one-on-one format. Players control either athlete and rely on shooting accuracy, defense, and positioning to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joshua-&-the-battle-of-jericho-usa-unl-v50', 'NES', 'Joshua & the Battle of Jericho (USA) (Unl) (v5.0)', '1992', 'Action', 'Unknown', '1', 'Religious Action', 'Top-down action adventure with religious themes', 'Complete biblical challenges and defeat enemies', 'A faith-based action game inspired by biblical stories', 'Joshua & the Battle of Jericho is a unique NES title combining action gameplay with biblical storytelling. Players guide Joshua through maze-like stages while overcoming enemies and obstacles rooted in religious themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joshua-&-the-battle-of-jericho-usa-unl-v60', 'NES', 'Joshua & the Battle of Jericho (USA) (Unl) (v6.0)', '1992', 'Action', 'Unknown', '1', 'Religious Action', 'Top-down action adventure with religious themes', 'Complete biblical challenges and defeat enemies', 'A faith-based action game inspired by biblical stories', 'Version 6.0 of Joshua & the Battle of Jericho refines gameplay and balance while maintaining its distinctive religious narrative. The game blends arcade action with spiritual themes uncommon on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('journey-to-silius-europe', 'NES', 'Journey to Silius (Europe)', '1990', 'Action', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling action platformer with shooting mechanics', 'Defeat enemies and survive futuristic stages', 'A cult-classic sci-fi action platformer', 'Journey to Silius is known for its intense action and acclaimed soundtrack. Players fight through mechanical enemies using advanced weapons in a dark science fiction setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('journey-to-silius-usa', 'NES', 'Journey to Silius (USA)', '1990', 'Action', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling action platformer with shooting mechanics', 'Defeat enemies and survive futuristic stages', 'A cult-classic sci-fi action platformer', 'This USA release of Journey to Silius delivers challenging gameplay, smooth controls, and memorable music. The game is praised as one of the finest action titles on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('journey-to-the-west-asia-unl', 'NES', 'Journey to the West (Asia) (Unl)', '1991', 'Action', 'Unknown', '1', 'Unlicensed Action', 'Action adventure with platforming and combat', 'Reach the end of the journey inspired by mythology', 'A mythological action game based on Journey to the West', 'Journey to the West draws inspiration from classic Chinese literature. Players navigate stages filled with enemies and traps, blending action, platforming, and fantasy elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joust-japan', 'NES', 'Joust (Japan)', '1983', 'Action', 'Atari', '2', 'Arcade Action', 'Arcade-style platformer with flying and combat mechanics', 'Defeat enemies and survive increasingly difficult waves', 'A classic arcade action game', 'Joust tasks players with flying atop a bird while battling enemies in floating arenas. The gameplay focuses on altitude control and timing, making it a timeless arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joust-usa', 'NES', 'Joust (USA)', '1983', 'Action', 'Atari', '2', 'Arcade Action', 'Arcade-style platformer with flying and combat mechanics', 'Defeat enemies and survive increasingly difficult waves', 'A classic arcade action game', 'This NES version of Joust faithfully recreates the original arcade gameplay, offering fast-paced action and simple yet highly addictive mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jovial-race-asia-unl-nes', 'NES', 'Jovial Race (Asia) (Unl) (NES)', '1992', 'Racing', 'Unknown', '2', 'Unlicensed Racing', 'Top-down racing game with obstacle avoidance', 'Finish races without crashing', 'A simple and colorful arcade racing game', 'Jovial Race is an unlicensed NES racing title featuring straightforward controls and bright visuals. Players navigate tracks while avoiding obstacles and maintaining speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jovial-race-unl', 'NES', 'Jovial Race (Unl)', '1992', 'Racing', 'Unknown', '2', 'Unlicensed Racing', 'Top-down racing game with obstacle avoidance', 'Finish races without crashing', 'A simple and colorful arcade racing game', 'This unlicensed version of Jovial Race offers quick arcade-style races with minimal complexity, focusing on reflexes and track memorization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joy-mech-fight-japan', 'NES', 'Joy Mech Fight (Japan)', '1993', 'Fighting', 'Nintendo', '2', 'Fighting', '2D Fighting.', 'Defeat the rogue robots and stop Dr. Walder''s world conquest.', 'A late-release masterpiece featuring fluid, limb-less robot fighters.', 'Using a brilliant animation technique, this game offers the most fluid 1-on-1 fighting experience on the NES, with over 30 playable characters and deep move sets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joy-mech-fight-japan-en-by-alanmidas-v20001214', 'NES', 'Joy Mech Fight (Japan) [En by AlanMidas v20001214]', '1993', 'Fighting', 'Nintendo', '2', 'Fighting', '2D Fighting.', 'Stop Dr. Walder with fully translated menus and story.', 'The English fan translation of Nintendo''s premier 8-bit fighter.', 'This version makes the robot upgrades and the humorous story accessible, allowing Western fans to enjoy one of the most technically impressive games on the Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juju-densetsu-japan', 'NES', 'JuJu Densetsu (Japan)', '1989', 'Action Platformer', 'Taito', '1', 'Action', 'Run and gun / Platformer.', 'Rescue your girlfriend as a human turned into a powerful ape.', 'The Japanese version of the arcade hit "Toki."', 'Players spit rapid-fire projectiles and navigate dangerous jungles. It''s known for its unique protagonist and challenging, deliberate platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumbo-ozaki-no-hole-in-one-professional-japan', 'NES', 'Jumbo Ozaki no Hole in One Professional (Japan)', '1988', 'Sports', 'Nintendo', '1', 'Sports', 'Sports / Golf.', 'Master the professional tour with the help of Jumbo Ozaki.', 'A detailed golf simulation featuring one of Japan''s greatest pros.', 'It offers a realistic approach to the sport, with deep menus for club selection and green reading, providing a high-quality 8-bit golfing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumpin-kid---jack-to-mame-no-ki-monogatari-japan', 'NES', 'Jumpin'' Kid - Jack to Mame no Ki Monogatari (Japan)', '1989', 'Action Platformer', 'Asmik', '1', 'Action', 'Side-scrolling platformer.', 'Climb the beanstalk to rescue the princess from the giants.', 'A creative 8-bit retelling of "Jack and the Beanstalk."', 'Players jump through clouds and castles, using various power-ups to defeat fairy-tale enemies in this colorful and charming Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-europe', 'NES', 'Jungle Book, The (Europe)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling action.', 'Help Mowgli navigate the jungle to reach the man-village.', 'A late-era platformer known for its exceptional animation and music.', 'Players collect gems and fruit while swinging on vines and dodging Shere Khan’s minions, showcasing some of the best visual work on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-usa', 'NES', 'Jungle Book, The (USA)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling action.', 'Help Mowgli navigate the jungle to reach the man-village.', 'A late-era platformer known for its exceptional animation and music.', 'Players collect gems and fruit while swinging on vines and dodging Shere Khan’s minions, showcasing some of the best visual work on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junkoid', 'NES', 'Junkoid', '1992', 'Action Platformer', 'Unknown', '1', 'Action', 'Action / Exploration.', 'Explore a post-apocalyptic world made of scrap to survive.', 'A modern "homebrew" style action game with a unique aesthetic.', 'Featuring a world built from garbage and mechanical parts, this title challenges players to scavenge and fight through non-linear 8-bit environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-boy-2-asia-unl', 'NES', 'Jurassic Boy 2 (Asia) (Unl)', '1991', 'Action Platformer', 'Unknown', '1', 'Action', 'Side-scrolling platformer.', 'Guide a young dinosaur through levels filled with hazards.', 'An unlicensed platformer heavily inspired by Sonic the Hedgehog.', 'This Chinese bootleg features fast-paced movement and loop-de-loops, attempting to replicate 16-bit "speed" platforming on the Famicom hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe', 'NES', 'Jurassic Park (Europe)', '1993', 'Action Adventure', 'Ocean Software', '1', 'Action', 'Top-down / Side-scrolling.', 'Rescue the guests and escape the island overrun by dinosaurs.', 'An ambitious movie tie-in featuring various gameplay perspectives.', 'Players must collect eggs and hack computers in a top-down view, occasionally switching to side-scrolling action to survive the prehistoric chaos of Isla Nublar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-usa', 'NES', 'Jurassic Park (USA)', '1993', 'Action Adventure', 'Ocean Software', '1', 'Action', 'Top-down / Side-scrolling.', 'Rescue the guests and escape the island overrun by dinosaurs.', 'An ambitious movie tie-in featuring various gameplay perspectives.', 'Players must collect eggs and hack computers in a top-down view, occasionally switching to side-scrolling action to survive the prehistoric chaos of Isla Nublar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('just-breed-japan', 'NES', 'Just Breed (Japan)', '1992', 'RPG', 'Random House / NCS', '1', 'RPG', 'Tactical RPG.', 'Lead a large army to protect the world from an ancient evil.', 'One of the most visually stunning strategy RPGs on the Famicom.', 'Utilizing Konami''s MMC5 chip, it features massive battles, detailed sprites, and a beautiful soundtrack, telling an epic story with deep tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('just-breed-japan-en-by-stealth-v10', 'NES', 'Just Breed (Japan) [En by Stealth v1.0]', '1992', 'RPG', 'Random House / NCS', '1', 'RPG', 'Tactical RPG.', 'Experience the epic Konami strategy tale in full English.', 'The essential English fan translation of this massive 8-bit RPG.', 'This version allows players to follow the complex plot and manage the many character classes and abilities that make Just Breed a masterpiece of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuouki-japan', 'NES', 'Juuouki (Japan)', '1988', 'Action Platformer', 'Westone', '1', 'Action', 'Side-scrolling beat ''em up.', 'Rise from your grave and transform into beasts to save Athena.', 'The Famicom port of Sega''s legendary "Altered Beast."', 'Despite the hardware limitations, this version captures the essence of the arcade, allowing players to power up and transform into wolves, dragons, and bears.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuouki-japan-en-by-aka-v10-~altered-beast', 'NES', 'Juuouki (Japan) [En by Aka v1.0] (~Altered Beast)', '1988', 'Action Platformer', 'Westone', '1', 'Action', 'Side-scrolling beat ''em up.', 'Transform into powerful beasts with translated menus.', 'An English fan translation of the Famicom version of Altered Beast.', 'This version provides a nostalgic experience of the Sega classic on Nintendo hardware, featuring fully translated text for the intro and beast power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuryoku-soukou-metal-storm-japan', 'NES', 'Juuryoku Soukou Metal Storm (Japan)', '1991', 'Action Platformer', 'Irem', '1', 'Action', 'Side-scrolling action.', 'Infiltrate the Cytron station and use gravity-shifting powers.', 'A technical marvel famous for its gravity-flipping mechanic.', 'Players control a mech that can flip between the floor and the ceiling instantly. It features incredible parallax scrolling and some of the best level design on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juvei-quest-japan', 'NES', 'Juvei Quest (Japan)', '1989', 'Action RPG', 'Seibu Kaihatsu', '1', 'RPG', 'Turn-based RPG.', 'Lead the young ninja Juvei on a quest to save the land of Kiba.', 'A large and humorous RPG featuring a wide world to explore.', 'Often compared to Dragon Quest, it features a unique "assistant" system and many mini-games, wrapped in a story full of traditional Japanese folklore and comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabuki---quantum-fighter-europe', 'NES', 'Kabuki - Quantum Fighter (Europe)', '1990', 'Action Platformer', 'Human Entertainment', '1', 'Action', 'Side-scrolling action.', 'Enter a computer mainframe as a digital Kabuki warrior.', 'A high-octane platformer with a unique "hair-whip" attack.', 'As Scott O''Connor, you fight through 8-bit cyberpunk levels. The game is praised for its tight controls, cinematic cutscenes, and intense boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabuki---quantum-fighter-usa', 'NES', 'Kabuki - Quantum Fighter (USA)', '1990', 'Action Platformer', 'Human Entertainment', '1', 'Action', 'Side-scrolling action.', 'Enter a computer mainframe as a digital Kabuki warrior.', 'A high-octane platformer with a unique "hair-whip" attack.', 'As Scott O''Connor, you fight through 8-bit cyberpunk levels. The game is praised for its tight controls, cinematic cutscenes, and intense boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabushiki-doujou-japan', 'NES', 'Kabushiki Doujou (Japan)', '1989', 'Board Game', 'Unknown', '2', 'Strategy', 'Simulation / Strategy.', 'Learn the ropes of the stock market to become a millionaire.', 'A stock market simulation game for the Famicom.', 'Players track charts, follow news, and make trades in a virtual Japanese economy, aiming to master the complexities of 8-bit financial investment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaettekita!-gunjin-shougi---nanya-sore!-japan', 'NES', 'Kaettekita! Gunjin Shougi - Nanya Sore! (Japan)', '1987', 'Action Platformer', 'Taito', '1', 'Action', 'Board game / Strategy.', 'Outsmart your opponent in a game of military-themed Shogi.', 'A quirky version of the classic Japanese strategy game.', 'It features a more casual and humorous presentation than traditional Shogi titles, making the tactical board game accessible to a wider audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kage-japan', 'NES', 'Kage (Japan)', '1986', 'Action Platformer', 'Taito', '1', 'Action', 'Side-scrolling action.', 'Infiltrate futuristic New York and defeat the dictator Garuda.', 'Known in the West as "Shadow of the Ninja" or "Blue Shadow."', 'A masterclass in ninja action, featuring two-player co-op, a grappling hook, and some of the best music and rain effects ever seen on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kage-no-densetsu-japan', 'NES', 'Kage no Densetsu (Japan)', '1989', 'Action Adventure', 'Unknown', '1', 'Action', 'Side-scrolling action.', 'Rescue Princess Kiri from the evil ninja army as Kage.', 'The Famicom version of Taito''s "The Legend of Kage."', 'Famous for its high-speed jumping and frantic sword fighting, players leap through forests and scale castle walls in this fast-paced arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kagerou-densetsu-japan', 'NES', 'Kagerou Densetsu (Japan)', '1986', 'Adventure', 'Namco', '1', 'Adventure', 'Adventure / Visual Novel.', 'Solve a series of mysteries in a story-driven supernatural world.', 'A text-based adventure featuring a strong atmosphere and art.', 'Players navigate through dialogue and menus to uncover the secrets of the "Mayfly Legend," focusing on character interactions and mystery-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaguya-hime-densetsu-japan', 'NES', 'Kaguya Hime Densetsu (Japan)', '1988', 'Action RPG', 'Birthday', '1', 'RPG', 'Text-based adventure with exploration and decision-making', 'Uncover the story by making correct choices', 'A Japanese folklore text adventure', 'Kaguya Hime Densetsu is a narrative-driven adventure game based on the classic Japanese tale of Princess Kaguya. Players read story text, make decisions, and explore locations to progress through the fairy-tale inspired plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaijuu-monogatari-japan', 'NES', 'Kaijuu Monogatari (Japan)', '1988', 'Action RPG', 'Birthday', '1', 'RPG', 'Turn-based RPG with exploration and party management', 'Defeat monsters and complete the story', 'A classic Japanese role-playing game', 'Kaijuu Monogatari is a traditional JRPG featuring turn-based battles, overworld exploration, and monster-filled dungeons. Players guide a party through a fantasy world while uncovering a heartfelt story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaijuu-monogatari-japan-en-by-kingmike-v10beta2-~shell-monsters-story', 'NES', 'Kaijuu Monogatari (Japan) [En by KingMike v1.0Beta2] (~Shell Monsters Story)', '1986', 'Action Platformer', 'Jaleco', '1', 'Action', 'Turn-based RPG with exploration and party management', 'Defeat monsters and complete the story', 'A classic Japanese role-playing game', 'This English-translated version of Kaijuu Monogatari allows wider audiences to experience its charming RPG mechanics, emotional narrative, and strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaiketsu-yanchamaru-japan', 'NES', 'Kaiketsu Yanchamaru (Japan)', '1987', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with melee combat', 'Defeat enemies and clear stages', 'A fast-paced ninja action game', 'Kaiketsu Yanchamaru is a side-scrolling platformer where players control a young ninja fighting through enemy-filled stages. The gameplay emphasizes quick attacks, precise jumps, and reflex-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaiketsu-yanchamaru-2---karakuri-land-japan', 'NES', 'Kaiketsu Yanchamaru 2 - Karakuri Land (Japan)', '1987', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with melee combat', 'Rescue the princess and defeat bosses', 'A colorful ninja platformer sequel', 'Kaiketsu Yanchamaru 2 expands on the original with improved level design and tougher enemies. Players navigate creative stages while battling foes in a lighthearted ninja-themed adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaiketsu-yanchamaru-2---karakuri-land-japan-en-by-d-v12-~kid-niki-2---karakuri-land', 'NES', 'Kaiketsu Yanchamaru 2 - Karakuri Land (Japan) [En by D v1.2] (~Kid Niki 2 - Karakuri Land)', '1987', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with melee combat', 'Rescue the princess and defeat bosses', 'A colorful ninja platformer sequel', 'Known in English as Kid Niki 2, this version offers classic NES action platforming with responsive controls, varied stages, and a whimsical presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaiketsu-yanchamaru-3---taiketsu!-zouringen-japan', 'NES', 'Kaiketsu Yanchamaru 3 - Taiketsu! Zouringen (Japan)', '1988', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with melee combat', 'Defeat enemies and complete the final adventure', 'The final entry in the Yanchamaru trilogy', 'Kaiketsu Yanchamaru 3 delivers more challenging levels and refined gameplay. Players face new enemies and obstacles in this concluding ninja action adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaiketsu-yanchamaru-3---taiketsu!-zouringen-japan-en-by-suicidal-v10-~kid-niki-3', 'NES', 'Kaiketsu Yanchamaru 3 - Taiketsu! Zouringen (Japan) [En by Suicidal v1.0] (~Kid Niki 3)', '1988', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with melee combat', 'Defeat enemies and complete the final adventure', 'The final entry in the Yanchamaru trilogy', 'This English-translated release of Kid Niki 3 allows players to enjoy its fast-paced platforming and colorful ninja action without language barriers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaizo-vania', 'NES', 'Kaizo Vania', '2019', 'Action Platformer', 'Fan Hack', '1', 'Action', 'Side-scrolling action platformer with extreme difficulty', 'Survive brutally hard stages', 'A hardcore Castlevania-style hack', 'Kaizo Vania is a fan-made hack designed for expert players. It features unforgiving enemy placement, precise jumps, and trial-and-error gameplay inspired by kaizo-style level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakefu-kun-no-jump-tengoku---speed-jigoku-japan', 'NES', 'Kakefu Kun no Jump Tengoku - Speed Jigoku (Japan)', '1987', 'Action Platformer', 'Namco', '1', 'Action', 'Side-scrolling platformer focused on jumping precision', 'Reach the end of each stage', 'A reflex-based action platformer', 'Kakefu Kun no Jump Tengoku challenges players with fast scrolling stages and demanding jumps. The game emphasizes timing, speed, and precision over combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kame-no-ongaeshi---urashima-densetsu-japan', 'NES', 'Kame no Ongaeshi - Urashima Densetsu (Japan)', '1986', 'Adventure', 'Unknown', '1', 'Adventure', 'Adventure game with exploration and puzzle-solving', 'Experience the folk tale and reach the ending', 'A Japanese folklore adventure', 'Kame no Ongaeshi - Urashima Densetsu retells the story of Urashima Taro through exploration and simple puzzles. The game focuses on narrative progression rather than action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-no-ninja---akakage-japan', 'NES', 'Kamen no Ninja - Akakage (Japan)', '1988', 'Action Platformer', 'Toei', '1', 'Action', 'Side-scrolling action game with ninja combat', 'Defeat enemies and complete missions', 'A classic ninja action game', 'Kamen no Ninja - Akakage features side-scrolling combat with ninja-themed enemies and stages. Players rely on quick attacks and careful movement to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-no-ninja---hanamaru-japan', 'NES', 'Kamen no Ninja - Hanamaru (Japan)', '1989', 'Action Platformer', 'Toei', '1', 'Action', 'Side-scrolling action game with ninja combat', 'Defeat enemies and complete missions', 'A classic ninja action game', 'Kamen no Ninja - Hanamaru builds upon its predecessor with refined mechanics and tougher challenges, offering fast-paced ninja action on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-club-japan', 'NES', 'Kamen Rider Club (Japan)', '1988', 'Action', 'Riverhillsoft', '1', 'Action', 'Side-scrolling action platformer with character switching', 'Defeat enemy riders and complete stages', 'A superhero action game', 'Kamen Rider Club lets players control different Kamen Riders, each with unique abilities. The game combines platforming and combat inspired by the popular tokusatsu series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-sd---granshocker-no-yabou-japan', 'NES', 'Kamen Rider SD - Granshocker no Yabou (Japan)', '1993', 'Action', 'Bandai', '1', 'Action', 'Side-scrolling action platformer with beat-em-up elements', 'Stop the evil organization', 'A super-deformed Kamen Rider action game', 'Kamen Rider SD features cute character designs combined with action-heavy gameplay. Players fight waves of enemies while progressing through themed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanshakudama-nage-kantarou-no-toukaidou-gojuusan-tsugi-japan', 'NES', 'Kanshakudama Nage Kantarou no Toukaidou Gojuusan Tsugi (Japan)', '1986', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action game with projectile combat', 'Complete stages across Japan', 'A comedic action adventure', 'Kanshakudama Nage Kantarou follows a bomb-throwing hero traveling across Japan. The gameplay blends action platforming with humorous visuals and historical references.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanshakudama-nage-kantarou-no-toukaidou-gojuusan-tsugi-japan-en-by-kingmike-v10-~kantaro-the-pyros-journey-across-the-toukaido', 'NES', 'Kanshakudama Nage Kantarou no Toukaidou Gojuusan Tsugi (Japan) [En by KingMike v1.0] (~Kantaro the Pyro''s Journey Across the Toukaido)', '1986', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action game with projectile combat', 'Complete stages across Japan', 'A comedic action adventure', 'This English-translated version of Kanshakudama Nage Kantarou makes its quirky humor and action accessible, featuring straightforward controls and stage-based progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karakuri-kengou-den---musashi-road---karakuri-nin-hashiru!-japan', 'NES', 'Karakuri Kengou Den - Musashi Road - Karakuri Nin Hashiru! (Japan)', '1987', 'Action RPG', 'Namco', '1', 'RPG', 'Side-scrolling action platformer with sword combat', 'Defeat enemies and clear mechanical stages', 'A mechanical ninja action game', 'Karakuri Kengou Den - Musashi Road combines traditional ninja action with mechanical-themed levels. Players engage in sword combat while navigating fast-paced side-scrolling stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karaoke-studio-japan', 'NES', 'Karaoke Studio (Japan)', '1987', 'Music', 'Nintendo', '1', 'Music', 'Music / Karaoke.', 'Sing along to popular songs and hit the notes to score points.', 'A unique Famicom peripheral that included a microphone.', 'This title turned the console into a karaoke machine, featuring simplified 8-bit versions of Japanese hits and a scoring system based on timing and pitch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karaoke-studio-senyou-cassette-vol-1-japan', 'NES', 'Karaoke Studio Senyou Cassette Vol. 1 (Japan)', '1987', 'Music', 'Nintendo', '1', 'Music', 'Music / Karaoke.', 'Expand your song library with new tracks and challenges.', 'An expansion pack for the Karaoke Studio peripheral.', 'This "Sub-Cartridge" adds a new selection of pop songs and enka classics, allowing owners of the base station to sing along to a wider variety of 8-bit hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karaoke-studio-senyou-cassette-vol-2-japan', 'NES', 'Karaoke Studio Senyou Cassette Vol. 2 (Japan)', '1987', 'Music', 'Nintendo', '1', 'Music', 'Music / Karaoke.', 'Expand your song library with a second set of hits.', 'The second expansion pack for Karaoke Studio.', 'Continuing the series, this volume added even more contemporary Japanese songs from the late 80s, keeping the home karaoke experience fresh for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karate-champ-usa', 'NES', 'Karate Champ (USA)', '1986', 'Fighting', 'Data East', '2', 'Fighting', '2D Fighting.', 'Defeat your opponent in a series of point-based karate matches.', 'A port of the influential Data East arcade fighting game.', 'Players use combinations of the D-pad and buttons to perform specific karate moves. The goal is to land clean hits to earn points and win the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karate-champ-usa-rev-a', 'NES', 'Karate Champ (USA) (Rev A)', '1986', 'Fighting', 'Data East', '2', 'Fighting', '2D Fighting.', 'Defeat your opponent in a series of point-based karate matches.', 'A revised version of the NES fighting classic with bug fixes.', 'This revision improves the hit detection and AI behavior, providing a slightly more polished version of the technical arcade brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karate-kid-the-usa', 'NES', 'Karate Kid, The (USA)', '1989', 'Action Platformer', 'LJN', '1', 'Action', 'Side-scrolling action.', 'Fight through the movie''s plot and win the All Valley Tournament.', 'An LJN action game based on the iconic martial arts film.', 'Players control Daniel LaRusso through levels based on Okinawa and the US, featuring the famous "Crane Kick" and various training mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karateka-japan', 'NES', 'Karateka (Japan)', '1985', 'Action Adventure', 'Jordan Mechner', '1', 'Action', 'Side-scrolling fighting.', 'Rescue Princess Mariko from the evil Akuma''s fortress.', 'A Famicom port of Jordan Mechner''s cinematic fighting game.', 'Known for its realistic animations and "one-hit kill" danger, it requires careful timing and stance-switching to survive guards and Akuma''s eagle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karateka-japan-beta', 'NES', 'Karateka (Japan) (Beta)', '1985', 'Action Adventure', 'Jordan Mechner', '1', 'Action', 'Side-scrolling fighting.', 'Rescue Princess Mariko in this early development version.', 'A rare prototype of the Famicom version of Karateka.', 'This version features slight differences in enemy AI and background colors, offering a look at how the Apple II classic was being adapted for Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karnov-japan', 'NES', 'Karnov (Japan)', '1987', 'Action Platformer', 'Data East', '1', 'Action', 'Side-scrolling action.', 'Find the lost treasure of Babylon as the fire-breathing strongman.', 'A unique Data East platformer starring the muscular Jinborov Karnovsky.', 'Karnov can breathe fire and use collected items like ladders and wings to navigate levels. It is famous for its strange enemy designs and challenging stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karnov-japan-en-by-vice-v11', 'NES', 'Karnov (Japan) [En by Vice v1.1]', '1987', 'Action Platformer', 'Data East', '1', 'Action', 'Side-scrolling action.', 'Find the lost treasure with fully translated English text.', 'The English fan translation of the Japanese Famicom version.', 'While the game was released in the US, this translation of the Famicom version preserves the original balance and Japanese menus for Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karnov-usa', 'NES', 'Karnov (USA)', '1988', 'Action Platformer', 'Data East', '1', 'Action', 'Side-scrolling action.', 'Find the lost treasure of Babylon as the fire-breathing strongman.', 'The North American release of the iconic fire-breathing platformer.', 'Players must manage their inventory of power-ups carefully to survive the surreal landscape and massive bosses of this 8-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kart-fighter-unl', 'NES', 'Kart Fighter (Unl)', '1994', 'Racing', 'Pirate', '2', 'Racing', '2D Fighting.', 'Win the fighting tournament using Mario and his racing friends.', 'A famous unlicensed fighting game featuring Mario Kart characters.', 'This Chinese bootleg uses the Street Fighter engine to put Mario, Luigi, Peach, and others in a 1v1 brawl. It is surprisingly playable for an unlicensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kart-fighter-improvement', 'NES', 'Kart Fighter Improvement', '1994', 'Racing', 'Pirate', '2', 'Racing', '2D Fighting.', 'Experience a balanced and fixed version of the bootleg fighter.', 'A fan-made "improvement" hack for the Kart Fighter bootleg.', 'This hack fixes broken hitboxes, balances damage, and cleans up the graphics, turning the weird bootleg into a much more competent 8-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawa-no-nushi-tsuri-japan', 'NES', 'Kawa no Nushi Tsuri (Japan)', '1987', 'Simulation', 'Pack-In-Video', '1', 'Simulation', 'Fishing RPG.', 'Travel the world to catch the legendary "King of the River."', 'A unique blend of fishing simulation and turn-based RPG.', 'As part of the "River King" series, players explore maps, talk to NPCs, and engage in RPG-style encounters, but the "battles" are actually fishing mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-simulation---honmei-japan', 'NES', 'Keiba Simulation - Honmei (Japan)', '1987', 'Sports', 'ASCII', '1', 'Sports', 'Sports / Horse Racing.', 'Analyze stats and place bets to win big at the horse track.', 'A detailed horse racing simulation for the Famicom.', 'This title focuses on the gambling and statistical side of racing, offering deep menus to track horse performance and breeding across multiple seasons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kekkyoku-nankyoku-daibouken-japan', 'NES', 'Kekkyoku Nankyoku Daibouken (Japan)', '1984', 'Action Platformer', 'Konami', '1', 'Action', 'Action / Racing.', 'Race against time to reach the research stations across Antarctica.', 'A classic Konami game starring Penta the penguin.', 'Players must dodge seals and pits while sliding across the ice. It is the first game in the series that eventually led to the "Parodius" franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kekkyoku-nankyoku-daibouken-japan-en-by-dvd-v10-~antarctic-adventure', 'NES', 'Kekkyoku Nankyoku Daibouken (Japan) [En by DvD v1.0] (~Antarctic Adventure)', '1984', 'Action Platformer', 'Konami', '1', 'Action', 'Action / Racing.', 'Reach the research stations with fully translated English menus.', 'The English fan translation of Konami''s "Kekkyoku Nankyoku Daibouken."', 'This version makes the travel distances and station names clear, allowing Western players to enjoy this early 8-bit Konami gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-keroppi-no-daibouken-japan', 'NES', 'Kero Kero Keroppi no Daibouken (Japan)', '1991', 'Action Platformer', 'Character Soft', '1', 'Action', 'Puzzle / Platformer.', 'Solve puzzles and rescue your friends in a colorful world.', 'A charming Sanrio-themed game starring the famous frog.', 'Featuring "Big Adventure," this game blends platforming with various brain-teasers and logic puzzles, all set in a bright and kid-friendly 8-bit environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-keroppi-no-daibouken-japan-en-by-gaijin-v10-~kero-kero-keroppis-big-adventure', 'NES', 'Kero Kero Keroppi no Daibouken (Japan) [En by Gaijin v1.0] (~Kero Kero Keroppi''s Big Adventure)', '1991', 'Action Platformer', 'Character Soft', '1', 'Action', 'Puzzle / Platformer.', 'Solve puzzles and rescue friends with translated instructions.', 'The English fan translation of the first Keroppi Famicom title.', 'This translation is essential for understanding the puzzle clues and level objectives, making the cute adventure fully playable for English speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-keroppi-no-daibouken-2---donuts-ike-ha-oosawagi!-japan', 'NES', 'Kero Kero Keroppi no Daibouken 2 - Donuts Ike ha Oosawagi! (Japan)', '1992', 'Action Platformer', 'Character Soft', '1', 'Action', 'Side-scrolling platformer.', 'Recover the stolen donuts and save Donut Pond.', 'An improved sequel focusing more on traditional platforming action.', 'Keroppi jumps through themed levels, using unique items to defeat enemies. It is known for its high-quality sprites and very polished gameplay for a licensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-keroppi-no-daibouken-2---donuts-ike-ha-oosawagi!-japan-en-by-spoony-bard-v10-~kero-kero-keroppis-great-big-adventure-2', 'NES', 'Kero Kero Keroppi no Daibouken 2 - Donuts Ike ha Oosawagi! (Japan) [En by Spoony Bard v1.0] (~Kero Kero Keroppi''s Great Big Adventure 2)', '1992', 'Action Platformer', 'Character Soft', '1', 'Action', 'Side-scrolling platformer.', 'Save Donut Pond with fully translated story and menus.', 'The English fan translation of the second Keroppi adventure.', 'This version allows players to follow the charming story and dialogue of the sequel while navigating its polished 8-bit platforming stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keroppi-to-keroriinu-no-splash-bomb!-japan', 'NES', 'Keroppi to Keroriinu no Splash Bomb! (Japan)', '1991', 'Action', 'Pack-In-Video', '1', 'Action', 'Top-down action game with bomb-based combat', 'Defeat enemies using splash bombs', 'A cute Sanrio-themed action game', 'Keroppi to Keroriinu no Splash Bomb! is a top-down action game where players control Keroppi and Keroriinu, throwing water bombs to defeat enemies across colorful stages inspired by the Sanrio universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keroppi-to-keroriinu-no-splash-bomb!-japan-en-by-suicidal-v10-~keroppi-&-keroleens-splash-bomb', 'NES', 'Keroppi to Keroriinu no Splash Bomb! (Japan) [En by Suicidal v1.0] (~Keroppi & Keroleen''s Splash Bomb)', '1991', 'Action', 'Pack-In-Video', '1', 'Action', 'Top-down action game with bomb-based combat', 'Defeat enemies using splash bombs', 'A cute Sanrio-themed action game', 'This English-translated version of Keroppi & Keroleen''s Splash Bomb allows players to enjoy its charming visuals and strategic bomb-based gameplay without language barriers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-master-usa', 'NES', 'Kick Master (USA)', '1992', 'Action Platformer', 'Taito', '1', 'Action', 'Side-scrolling action platformer with martial arts combat', 'Defeat enemies using powerful kicks', 'A fast-paced martial arts platformer', 'Kick Master features fluid animation and unique kick-based combat. Players battle monsters using acrobatic moves and precise timing across challenging stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-off-europe', 'NES', 'Kick Off (Europe)', '1989', 'Sports', 'Anco', '2', 'Sports', 'Top-down soccer simulation', 'Score goals and win matches', 'A classic soccer sports game', 'Kick Off delivers fast-paced soccer action with simple controls and an overhead view. The game focuses on quick matches and arcade-style gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kickle-cubicle-europe', 'NES', 'Kickle Cubicle (Europe)', '1990', 'Puzzle', 'Irem', '2', 'Puzzle', 'Isometric puzzle game with block manipulation', 'Solve puzzles and clear rooms', 'A clever isometric puzzle adventure', 'Kickle Cubicle challenges players to push ice blocks to defeat enemies and solve room-based puzzles using logic and spatial awareness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kickle-cubicle-usa', 'NES', 'Kickle Cubicle (USA)', '1990', 'Puzzle', 'Irem', '2', 'Puzzle', 'Isometric puzzle game with block manipulation', 'Solve puzzles and clear rooms', 'A clever isometric puzzle adventure', 'The USA version of Kickle Cubicle offers the same polished puzzle gameplay, featuring charming visuals and progressively challenging stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-icarus---angel-land-story-europe-rev-a', 'NES', 'Kid Icarus - Angel Land Story (Europe) (Rev A)', '1986', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling action platformer with exploration', 'Defeat Medusa and save Angel Land', 'A mythological action-adventure', 'Kid Icarus combines platforming, shooting, and RPG elements. Players guide Pit through vertically scrolling stages inspired by Greek mythology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-icarus---angel-land-story-usa-europe', 'NES', 'Kid Icarus - Angel Land Story (USA, Europe)', '1986', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling action platformer with exploration', 'Defeat Medusa and save Angel Land', 'A mythological action-adventure', 'This version of Kid Icarus delivers classic NES gameplay featuring challenging levels, power-ups, and non-linear progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-klown-in-night-mayor-world-usa', 'NES', 'Kid Klown in Night Mayor World (USA)', '1992', 'Action Platformer', 'Kemco', '1', 'Action', 'Side-scrolling platformer with cartoon visuals', 'Rescue the dream world', 'A whimsical cartoon platformer', 'Kid Klown in Night Mayor World is a colorful platformer featuring imaginative enemies and creative level design inspired by dream-like environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-kool-and-the-quest-for-the-seven-wonder-herbs-usa', 'NES', 'Kid Kool and the Quest for the Seven Wonder Herbs (USA)', '1988', 'Action Platformer', 'Poppo', '1', 'Action', 'Side-scrolling platformer with environmental hazards', 'Collect herbs and save the day', 'A quirky action platformer', 'Kid Kool and the Quest for the Seven Wonder Herbs emphasizes obstacle avoidance and stage memorization, offering a unique but challenging platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-niki---radical-ninja-usa', 'NES', 'Kid Niki - Radical Ninja (USA)', '1987', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with ninja combat', 'Defeat enemies and rescue the princess', 'A classic ninja platformer', 'Kid Niki - Radical Ninja features fast-paced platforming, sword combat, and colorful environments as players fight through enemy-filled stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-niki---radical-ninja-usa-rev-a', 'NES', 'Kid Niki - Radical Ninja (USA) (Rev A)', '1987', 'Action Platformer', 'Jaleco', '1', 'Action', 'Side-scrolling action platformer with ninja combat', 'Defeat enemies and rescue the princess', 'A classic ninja platformer', 'This revised version of Kid Niki offers the same energetic ninja action with minor refinements and balanced gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-kong-2---ikari-no-megaton-punch-japan', 'NES', 'King Kong 2 - Ikari no Megaton Punch (Japan)', '1986', 'Action Platformer', 'Konami', '1', 'Action', 'Side-scrolling action platformer with giant enemies', 'Defeat King Kong and survive stages', 'A cinematic action platformer', 'King Kong 2 - Ikari no Megaton Punch blends platforming and combat, featuring large enemy sprites and dramatic boss encounters inspired by the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-kong-2---ikari-no-megaton-punch-japan-en-by-dvd-rev-a-~king-kong-lives---megaton-punch-of-rage', 'NES', 'King Kong 2 - Ikari no Megaton Punch (Japan) [En by DvD Rev A] (~King Kong Lives - Megaton Punch of Rage)', '1987', 'Action Platformer', 'Konami', '1', 'Action', 'Side-scrolling action platformer with giant enemies', 'Defeat King Kong and survive stages', 'A cinematic action platformer', 'This English-translated version allows players to experience the intense platforming and cinematic battles against massive foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-neptunes-adventure-usa-unl', 'NES', 'King Neptune''s Adventure (USA) (Unl)', '1990', 'Action Platformer', 'Camelot', '1', 'Action', 'Side-scrolling action platformer', 'Explore stages and defeat enemies', 'An unofficial fantasy adventure', 'King Neptune''s Adventure is an unlicensed NES game featuring traditional platforming and simple combat across fantasy-themed levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-kings-japan', 'NES', 'King of Kings (Japan)', '1988', 'Action', 'Bullet-Proof Software', '1', 'Action', 'Action-adventure with biblical themes', 'Defeat evil forces from a biblical perspective', 'A faith-based action game', 'King of Kings combines top-down action and narrative inspired by biblical stories, focusing on moral themes and symbolic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-kings-the-usa-unl-v11', 'NES', 'King of Kings, The (USA) (Unl) (v1.1)', '1990', 'Action', 'Bullet-Proof Software', '1', 'Action', 'Action-adventure with biblical themes', 'Defeat evil forces from a biblical perspective', 'A faith-based action game', 'This unlicensed release of The King of Kings presents similar gameplay with minor variations, emphasizing religious storytelling through action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-kings-the-usa-unl-v12', 'NES', 'King of Kings, The (USA) (Unl) (v1.2)', '1990', 'Action', 'Bullet-Proof Software', '1', 'Action', 'Action-adventure with biblical themes', 'Defeat evil forces from a biblical perspective', 'A faith-based action game', 'Version 1.2 continues the same structure, offering small gameplay tweaks while maintaining its biblical focus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-kings-the-usa-unl-v13', 'NES', 'King of Kings, The (USA) (Unl) (v1.3)', '1990', 'Action', 'Bullet-Proof Software', '1', 'Action', 'Action-adventure with biblical themes', 'Defeat evil forces from a biblical perspective', 'A faith-based action game', 'Version 1.3 refines enemy behavior and balance while preserving the original religious action-adventure experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-kings-the-usa-unl-v50', 'NES', 'King of Kings, The (USA) (Unl) (v5.0)', '1990', 'Action', 'Bullet-Proof Software', '1', 'Action', 'Action-adventure with biblical themes', 'Defeat evil forces from a biblical perspective', 'A faith-based action game', 'Version 5.0 features further adjustments, making it the most polished release of this unlicensed biblical NES title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-knight-japan', 'NES', 'King''s Knight (Japan)', '1986', 'Action RPG', 'Square', '1', 'RPG', 'Vertical scrolling action shooter', 'Reach the end of each area', 'A fantasy vertical shooter', 'King''s Knight mixes vertical shooting with fantasy themes, requiring players to guide characters through enemy-filled corridors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-knight-usa', 'NES', 'King''s Knight (USA)', '1986', 'Action RPG', 'Square', '1', 'RPG', 'Vertical scrolling action shooter', 'Reach the end of each area', 'A fantasy vertical shooter', 'The USA version of King''s Knight offers the same challenging shooter mechanics with localized text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-quest-v-usa', 'NES', 'King''s Quest V (USA)', '1992', 'Adventure', 'Sierra', '1', 'Adventure', 'Point-and-click adventure with puzzles', 'Complete the story and solve puzzles', 'A classic graphic adventure', 'King''s Quest V brings the famous PC adventure series to the NES, featuring story-driven gameplay, puzzles, and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-of-the-beach---professional-beach-volleyball-usa', 'NES', 'Kings of the Beach - Professional Beach Volleyball (USA)', '1990', 'Sports', 'Electronic Arts', '2', 'Sports', 'Sports game with volleyball mechanics', 'Win beach volleyball tournaments', 'A competitive beach volleyball game', 'Kings of the Beach offers arcade-style volleyball gameplay with professional players, emphasizing timing and positioning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinnikuman---muscle-tag-match-japan', 'NES', 'Kinnikuman - Muscle Tag Match (Japan)', '1985', 'Fighting', 'Bandai', '2', 'Fighting', 'Wrestling / Fighting.', 'Defeat your opponents in a tag-team wrestling tournament.', 'A cult classic wrestling game based on the popular anime.', 'Players choose two wrestlers and fight in a ring where items are thrown from the sidelines. It is famous for its simple but addictive competitive gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinnikuman---muscle-tag-match-japan-rev-1', 'NES', 'Kinnikuman - Muscle Tag Match (Japan) (Rev 1)', '1985', 'Fighting', 'Bandai', '2', 'Fighting', 'Wrestling / Fighting.', 'Defeat your opponents with updated game balance.', 'A revised version of the Famicom wrestling hit.', 'This revision fixes minor graphical glitches and balances some of the characters'' special moves to make the tag-team matches fairer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinnikuman---muscle-tag-match-japan-en-by-stardust-crusaders-v10', 'NES', 'Kinnikuman - Muscle Tag Match (Japan) [En by Stardust Crusaders v1.0]', '1985', 'Fighting', 'Bandai', '2', 'Fighting', 'Wrestling / Fighting.', 'Win the wrestling tournament with translated menus.', 'The English fan translation of the Japanese Kinnikuman game.', 'This version replaces the Japanese text with English, making the character selection and win screens accessible for Western fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinnikuman:-dreammatch', 'NES', 'Kinnikuman: Dreammatch', '1993', 'Fighting', 'Pirate', '2', 'Fighting', 'Wrestling / Fighting.', 'Compete in a dream tournament with iconic characters.', 'A specialized version or hack focusing on character matchups.', 'Often a modified version of the original engine, it allows for unique pairings and faster gameplay for fans of the Muscle Tag Match style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-hack', 'NES', 'Kirby Hack', '1992', 'Hack', 'Hack', '1', 'Hack', 'Side-scrolling platformer.', 'Explore modified levels with new abilities or colors.', 'A general term for fan-made modifications of Kirby''s Adventure.', 'These hacks often change Kirby’s color, enemy placements, or even create entirely new worlds using the high-quality Kirby engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure---heaven-or-hell-difficulty', 'NES', 'Kirby''s Adventure - Heaven or Hell Difficulty', '1992', 'Hack', 'Hack', '1', 'Hack', 'Side-scrolling platformer.', 'Survive an extremely high-difficulty version of Kirby''s quest.', 'A difficulty hack that pushes player skills to the limit.', 'This version remakes enemy placements and damage values to provide a brutal challenge, far beyond the accessibility of the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-canada', 'NES', 'Kirby''s Adventure (Canada)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Recover the Star Rod in this bilingual Canadian release.', 'The classic Kirby adventure with English and French support.', 'Featuring the same ground-breaking graphics and copy abilities, this version was distributed specifically for the Canadian market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-europe', 'NES', 'Kirby''s Adventure (Europe)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Recover the Star Rod and restore dreams to Dream Land.', 'The PAL version of Kirby''s massive 8-bit masterpiece.', 'One of the largest NES games ever made, it features 7 worlds, incredible boss fights, and the iconic "copy" mechanic that defined the character.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-france', 'NES', 'Kirby''s Adventure (France)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Restore the Star Rod in this French-language edition.', 'A fully localized version of Kirby''s Adventure for France.', 'This version translates all the menus and instructions into French, ensuring fans in the region could enjoy the story of Dream Land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-germany', 'NES', 'Kirby''s Adventure (Germany)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Restore the Star Rod in this German-language edition.', 'A fully localized version of Kirby''s Adventure for Germany.', 'This version features German text for all the in-game menus and story beats, maintaining the high quality of the 8-bit original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-usa', 'NES', 'Kirby''s Adventure (USA)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Recover the Star Rod and restore dreams to Dream Land.', 'The definitive North American release of Kirby''s NES debut.', 'Introducing the "copy ability" for the first time, it pushed the NES hardware with its vibrant colors, parallax scrolling, and huge memory capacity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-adventure-usa-rev-a', 'NES', 'Kirby''s Adventure (USA) (Rev A)', '1993', 'Action Platformer', 'Nintendo', '1', 'Action', 'Side-scrolling platformer.', 'Restore dreams with minor technical and text fixes.', 'A revised North American release of the 8-bit classic.', 'This revision fixes minor spelling errors and addresses rare saving glitches found in the first production run of the cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbyâ€™s-adventure-2', 'NES', 'Kirbyâ€™s Adventure 2', '1995', 'Action Platformer', 'Fan Hack', '1', 'Action', 'Side-scrolling platformer.', 'Continue Kirby''s journey in this fan-made sequel or hack.', 'Often a title used for hacks or the GBA remake''s 8-bit backport.', 'This version typically features new levels or a mix of Game Boy stages brought into the NES Kirby engine for a "sequel" feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiteretsu-dai-hyakka-japan', 'NES', 'Kiteretsu Dai Hyakka (Japan)', '1988', 'Adventure', 'Namco', '1', 'Adventure', 'Side-scrolling action.', 'Help Kiteretsu and Korosuke navigate through surreal levels.', 'A creative action game based on the anime by Doraemon''s creator.', 'Known for its unique physics (including upside-down gravity segments), players use inventions to solve puzzles and defeat enemies in a colorful world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiwi-kraze---a-bird-brained-adventure!-usa', 'NES', 'Kiwi Kraze - A Bird-Brained Adventure! (USA)', '1992', 'Action Platformer', 'Software Creations', '1', 'Action', 'Side-scrolling platformer.', 'Rescue your kiwi friends from the leopard seal''s zoo.', 'The NES version of the arcade hit "The NewZealand Story."', 'As Tiki the kiwi, you navigate complex mazes using a bow and arrow, flying in balloons, and swimming through trap-filled waters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klash-ball-usa', 'NES', 'Klash Ball (USA)', '1991', 'Sports', 'Taito', '2', 'Sports', 'Sports / Futuristic.', 'Score goals in a brutal, high-tech version of handball.', 'A futuristic sports game by Softek International.', 'Combining elements of soccer and combat, players can tackle and hit opponents while trying to throw a metallic ball into the goal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-japan', 'NES', 'Klax (Japan)', '1990', 'Puzzle', 'Tengen', '2', 'Puzzle', 'Puzzle.', 'Catch colored tiles and arrange them into rows or patterns.', 'The Famicom version of the popular Atari arcade puzzle game.', 'Tiles roll down a conveyor belt, and you must catch them on a paddle and drop them to create "Klaxes" of three or more identical colors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-usa-unl', 'NES', 'Klax (USA) (Unl)', '1990', 'Puzzle', 'Tengen', '2', 'Puzzle', 'Puzzle.', 'Catch colored tiles and arrange them into rows or patterns.', 'The unlicensed Tengen version of the tile-matching hit.', 'Featuring the same addictive "It is the 90s and there is time for Klax" gameplay, this version was sold in a black cartridge outside of Nintendo''s license.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knight-rider-europe', 'NES', 'Knight Rider (Europe)', '1989', 'Action', 'Atari', '1', 'Action', 'Racing / Combat.', 'Use K.I.T.T.''s high-tech weapons to stop criminal organizations.', 'A combat-racing game based on the hit 80s TV series.', 'Players drive from a first-person perspective, using turbo boosts and missiles to destroy enemy vehicles and reach the mission target on time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knight-rider-japan', 'NES', 'Knight Rider (Japan)', '1989', 'Action', 'Atari', '1', 'Action', 'Racing / Combat.', 'Use K.I.T.T.''s high-tech weapons to stop criminal organizations.', 'The Famicom version of the "El Auto Fantástico" adventure.', 'It features the same high-speed combat and upgrades, allowing players to feel like Michael Knight in an 8-bit technological thriller.');
