INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-hyper-soccer-europe', 'NES', 'Konami Hyper Soccer (Europe)', '1992', 'Sports', 'Konami', '2', 'Sports', 'Sports / Soccer.', 'Win the international tournament in this high-speed soccer sim.', 'One of Konami''s best sports efforts on the NES.', 'Featuring a unique overhead perspective and smooth scrolling, it offers intense arcade gameplay with overhead kicks and varied team strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konamic-sports-in-seoul-japan', 'NES', 'Konamic Sports in Seoul (Japan)', '1988', 'Sports', 'Konami', '2', 'Sports', 'Sports compilation with multiple Olympic events', 'Win medals in athletic competitions', 'An Olympic-style sports collection', 'Konamic Sports in Seoul features a variety of sports events inspired by the Olympic Games, allowing players to compete in track, field, and other athletic challenges.');
