INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lin-ze-xu-jin-yan-china-unl', 'NES', 'Lin Ze Xu Jin Yan (China) (Unl)', '1990', 'Action', 'Unlicensed', '1', 'Side-scrolling', 'Narrative-driven historical adventure', 'Complete the historical storyline', 'A Chinese historical action game', 'Lin Ze Xu Jin Yan is an unlicensed NES game inspired by Chinese history, combining storytelling with action-oriented gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('linus-spaceheads-cosmic-crusade-usa-enfrdees-unl', 'NES', 'Linus Spacehead''s Cosmic Crusade (USA) (En,Fr,De,Es) (Unl)', '1992', 'Platform/Adventure', 'Codemasters', '1', 'Side-scrolling', 'Adventure / Platform.', 'Collect radio parts to fix your ship and return home.', 'A colorful Codemasters adventure with a multi-lingual twist.', 'Players guide Linus through varied stages, blending platforming with light puzzle-solving and item collection, featuring a distinct European 8-bit art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-1995-unl', 'NES', 'Lion King, The (1995) (Unl)', '1995', 'Platform', 'Unlicensed', '1', 'Side-scrolling', 'Side-scrolling action.', 'Help Simba grow from a cub to a king and defeat Scar.', 'An unlicensed but famous demake of the 16-bit classic.', 'This bootleg version attempts to recreate the SNES/Genesis experience, featuring several iconic levels and simplified versions of the original''s music and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-europe', 'NES', 'Lion King, The (Europe)', '1995', 'Platform', 'Westwood Studios', '1', 'Side-scrolling', 'Side-scrolling action.', 'Help Simba grow from a cub to a king and defeat Scar.', 'The official Virgin Interactive release, one of the last for NES.', 'Known for being technically impressive and extremely difficult, it features smooth animations and level designs that stay very close to the 16-bit versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-super-game-unl', 'NES', 'Lion King, The (Super Game) (Unl)', '1995', 'Platform', 'Unlicensed', '1', 'Side-scrolling', 'Side-scrolling action.', 'Navigate Simba through the Pride Lands to reclaim the throne.', 'Another unlicensed variation of the Disney hit.', 'Developed by the "Super Game" team, this version has different physics and sprite work than other bootlegs, showing how popular the movie was in the 8-bit pirate market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lipple-island-japan', 'NES', 'Lipple Island (Japan)', '1983', 'Puzzle/Platform', 'Sunsoft', '1', 'Single-screen', 'Adventure.', 'Explore the island and solve puzzles to win a royal competition.', 'A charming, menu-based point-and-click adventure.', 'Featuring bright, "Kawaii" graphics, players interact with the environment and quirky characters to progress through a fairy-tale story on the Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-league-baseball---championship-series-usa', 'NES', 'Little League Baseball - Championship Series (USA)', '1990', 'Sports', 'SNK', '1-2', 'Top-down/Side view', 'Sports / Baseball.', 'Lead a team of kids to the Little League World Series title.', 'A fan-favorite baseball game known for its accessibility and fun.', 'It features varied team stats and "power" mechanics, offering a more lighthearted but still strategic take on baseball compared to professional sims.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-japan', 'NES', 'Little Magic (Japan)', '1993', 'Puzzle', 'Altron', '1', 'Top-down', 'Puzzle / Platformer.', 'Use your magic bubble to push stones and clear the exit.', 'A clever and cute logic-based puzzle game.', 'As a young witch-in-training, you must master the physics of your magical bubbles to move obstacles and navigate increasingly complex single-screen rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-japan-en-by-gaijin+transbrc-v033alpha-incomplete', 'NES', 'Little Magic (Japan) [En by Gaijin+TransBRC v0.33Alpha] (Incomplete)', '1993', 'Puzzle', 'Altron', '1', 'Top-down', 'Puzzle / Platformer.', 'Clear the puzzle rooms with translated menus and hints.', 'An English fan translation of the Famicom puzzle gem.', 'Although incomplete in some areas, this patch makes the level instructions and UI accessible for English-speaking puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-mermaid---ningyo-hime-japan', 'NES', 'Little Mermaid - Ningyo Hime (Japan)', '1991', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat Ursula and her minions to save the sea kingdom.', 'The Japanese version of Capcom''s underwater adventure.', 'Players control Ariel, using her tail to trap enemies in bubbles and throw them. It’s known for its beautiful 8-bit colors and high Capcom production value.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-mermaid-the-usa', 'NES', 'Little Mermaid, The (USA)', '1991', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat Ursula and her minions to save the sea kingdom.', 'A polished Capcom platformer based on the Disney movie.', 'A perfect game for younger players that still offers tight mechanics, featuring creative boss fights and excellent music composed by Capcom''s veteran staff.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-nemo---the-dream-master-europe', 'NES', 'Little Nemo - The Dream Master (Europe)', '1990', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Travel through Slumberland to defeat the Nightmare King.', 'A dreamy Capcom platformer based on the classic comic strip.', 'Nemo uses candy to tame various animals, allowing him to ride them and use their abilities (climbing, flying, swimming) to collect keys and progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-nemo---the-dream-master-usa', 'NES', 'Little Nemo - The Dream Master (USA)', '1990', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Travel through Slumberland to defeat the Nightmare King.', 'A dreamy Capcom platformer based on the classic comic strip.', 'Nemo uses candy to tame various animals, allowing him to ride them and use their abilities (climbing, flying, swimming) to collect keys and progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-ninja-brothers-europe', 'NES', 'Little Ninja Brothers (Europe)', '1990', 'Action RPG', 'Culture Brain', '1-2', 'Top-down', 'Action RPG / Party.', 'Stop the Bluaberry King and save Chinaland.', 'A unique blend of RPG exploration and real-time action.', 'Players control Jack and Ryu in a world filled with humor, featuring top-down exploration and side-scrolling "battle" segments that can be played cooperatively.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-ninja-brothers-usa', 'NES', 'Little Ninja Brothers (USA)', '1990', 'Action RPG', 'Culture Brain', '1-2', 'Top-down', 'Side-scrolling action.', 'Navigate the forest to reach Grandma''s house safely.', 'A notoriously difficult unlicensed game by Sachen.', 'Far from the fairy tale, this game features aggressive enemies and complex level layouts, requiring the collection of fruit and money to survive the journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-red-hood---xiao-hong-mao-asia-unl-sachen-famicom', 'NES', 'Little Red Hood - Xiao Hong Mao (Asia) (Unl) (Sachen) (Famicom)', '1989', 'Action', 'Sachen', '1', 'Side-scrolling', 'Side-scrolling action.', 'Survive the forest in this Australian unlicensed release.', 'The Australian HES version of the Sachen original.', 'Known for its rarity and frustrating difficulty, it maintains the strange mechanics and surreal 8-bit graphics of the original Chinese development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-red-hood-australia-unl-hes', 'NES', 'Little Red Hood (Australia) (Unl) (HES)', '1989', 'Action', 'Sachen/HES', '1', 'Side-scrolling', 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-samson-europe', 'NES', 'Little Samson (Europe)', '1992', 'Platform/Action', 'Takeru', '1', 'Side-scrolling', 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-samson-usa', 'NES', 'Little Samson (USA)', '1992', 'Platform/Action', 'Takeru', '1', 'Side-scrolling', 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('locksmith-asia-unl-nes', 'NES', 'Locksmith (Asia) (Unl) (NES)', '1991', 'Puzzle', 'Unlicensed', '1', 'Single-screen', 'Puzzle.', 'Unlock various locks by matching patterns and symbols.', 'A simple but addictive unlicensed logic game.', 'Testing the player''s memory and speed, it presents a series of "safes" that must be cracked under a time limit, featuring basic but functional 8-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-japan', 'NES', 'Lode Runner (Japan)', '1984', 'Puzzle/Platform', 'Broderbund/Hudson Soft', '1', 'Single-screen', 'Puzzle / Platformer.', 'Collect all the gold in each level while avoiding guards.', 'A classic and highly addictive puzzle-action port.', 'Players must dig holes to trap enemies and reach platforms. The Famicom version is famous for its large sprites and the included level editor mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-usa', 'NES', 'Lode Runner (USA)', '1983', 'Puzzle/Platform', 'Broderbund', '1-2', 'Single-screen', 'Puzzle / Platformer.', 'Collect all the gold in each level while avoiding guards.', 'A classic and highly addictive puzzle-action port.', 'Players must dig holes to trap enemies and reach platforms. The Famicom version is famous for its large sprites and the included level editor mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lone-ranger-the-usa', 'NES', 'Lone Ranger, The (USA)', '1987', 'Action/Adventure', 'Konami', '1', 'Side-scrolling', 'Action Adventure.', 'Stop the villainous Butch Cavendish in the Wild West.', 'An ambitious Konami title with multiple gameplay styles.', 'It features side-scrolling action, top-down exploration, and even first-person shooting segments (compatible with the Zapper), all wrapped in an epic western story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('loopz-usa', 'NES', 'Loopz (USA)', '1990', 'Puzzle', 'Audiogenic', '1-2', 'Top-down', 'Puzzle.', 'Connect pipe pieces to form closed loops and clear the screen.', 'A challenging and unique geometric puzzle game.', 'Pieces appear randomly, and you must place them strategically. It requires fast thinking and spatial awareness to keep the board from filling up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-king-the-japan', 'NES', 'Lord of King, The (Japan)', '1988', 'Action RPG', 'Namco', '1', 'Top-down', 'Side-scrolling action.', 'Defeat the dark wizard and his monsters in a fantasy world.', 'The Japanese version of "The Astyanax."', 'As a young hero with a magical axe, you fight through lushly detailed mythical levels, featuring huge bosses and impressive cinematic cutscenes for its time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-word-of-jenny---ushinawareta-message-japan', 'NES', 'Lost Word of Jenny - Ushinawareta Message (Japan)', '1987', 'Adventure', 'Takeru', '1', 'Side-scrolling', 'Narrative adventure with puzzles', 'Uncover the lost message', 'A mystery adventure game', 'Lost Word of Jenny is a story-driven adventure focusing on exploration, dialogue, and puzzle-solving to uncover a mysterious missing message.');
