INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mach-rider-europe', 'NES', 'Mach Rider (Europe)', '1985', 'Racing/Action', 'Nintendo', '1', 'Third-person', 'Motorcycle racing action', 'Win high-speed races', 'A futuristic racing game', 'Mach Rider combines motorcycle racing with combat elements in a post-apocalyptic setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mach-rider-japan-usa', 'NES', 'Mach Rider (Japan, USA)', '1985', 'Racing/Action', 'Nintendo', '1', 'Third-person', 'Combat racing.', 'Race through futuristic highways and destroy enemy bikers.', 'A high-speed, post-apocalyptic motorcycle racer by Nintendo.', 'Set in the year 2112, players must dodge obstacles and use machine guns to clear the road. It also features a "Design Mode" to create custom tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mach-rider-japan-usa-rev-a', 'NES', 'Mach Rider (Japan, USA) (Rev A)', '1985', 'Racing/Action', 'Nintendo', '1', 'Third-person', 'Combat racing.', 'Race through futuristic highways with improved stability.', 'A revised version of the classic Nintendo motorcycle racer.', 'This update fixes minor sprite flickering and addresses small bugs in the track editor, providing a smoother experience of the high-speed combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mad-city-japan', 'NES', 'Mad City (Japan)', '1987', 'Action', 'Capcom', '1', 'Top-down', 'Action hybrid.', 'Rescue your girlfriend Annabelle from the gang leader.', 'The original Japanese version of "The Adventures of Bayou Billy."', 'It combines side-scrolling brawling, driving, and Zapper shooting. This version is notably easier and more balanced than its Western counterpart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mad-city-japan-beta', 'NES', 'Mad City (Japan) (Beta)', '1987', 'Action', 'Capcom', '1', 'Top-down', 'Action hybrid.', 'Rescue Annabelle in this early development version.', 'A rare prototype of the multi-genre Konami title.', 'This beta shows early level layouts and different difficulty settings, offering a look at how Konami integrated three different gameplay styles into one cart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mad-max-usa', 'NES', 'Mad Max (USA)', '1990', 'Racing/Action', 'Mindscape', '1', 'Top-down', 'Post-apocalyptic driving.', 'Survive the wasteland and defeat the rival gangs.', 'A vehicle-based combat game based on the movie franchise.', 'Players drive through arena-like stages, scavenging for fuel and water while upgrading their car''s weapons to survive an 8-bit desert dystopia.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-block-unl', 'NES', 'Magic Block (Unl)', '1991', 'Puzzle', 'Unlicensed', '1-2', 'Single-screen', 'Falling-block puzzle.', 'Align identical symbols to clear blocks from the screen.', 'An unlicensed puzzle game with a magical aesthetic.', 'Similar to "Columns," players must arrange falling symbols vertically, horizontally, or diagonally to prevent the screen from filling up in this 8-bit bootleg.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-candle-the-japan', 'NES', 'Magic Candle, The (Japan)', '1991', 'RPG', 'Nexoft', '1', 'Top-down', 'Turn-based RPG.', 'Find a way to keep the magical candle burning and trap a demon.', 'A Famicom port of the complex Western PC RPG.', 'Known for its non-linear world and party management, players must assign tasks to their companions to solve puzzles and prevent the world''s destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-carpet-1001-unl', 'NES', 'Magic Carpet 1001 (Unl)', '1991', 'Puzzle', 'Unlicensed', '1', 'Single-screen', 'Side-scrolling shooter.', 'Fly a magic carpet through the desert and defeat mystical foes.', 'An unlicensed shooter by Caltron / Myriad.', 'Players control a character on a flying carpet, dodging projectiles and shooting enemies in a simple but challenging 8-bit action loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-cube-asia-unl-nes', 'NES', 'Magic Cube (Asia) (Unl) (NES)', '1990', 'Puzzle', 'Unlicensed', '1-2', 'Single-screen', 'Puzzle.', 'Solve various cube-based logic and spatial puzzles.', 'An unlicensed 8-bit take on the Rubik''s Cube style of gaming.', 'It challenges the player''s spatial reasoning through several modes, requiring them to manipulate blocks to match specific patterns under a time limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-darts-japan', 'NES', 'Magic Darts (Japan)', '1990', 'Sports', 'Human Entertainment', '1-4', 'Side view', 'Sports / Darts.', 'Compete in a professional darts tournament to be the best.', 'A realistic darts simulation featuring diverse characters.', 'Players must manage timing and aim to hit specific targets on the board, offering a surprisingly deep 8-bit representation of the pub sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-darts-usa', 'NES', 'Magic Darts (USA)', '1990', 'Sports', 'Romstar', '1-4', 'Side view', 'Sports / Darts.', 'Compete in a professional darts tournament to be the best.', 'A realistic darts simulation featuring diverse characters.', 'Players must manage timing and aim to hit specific targets on the board, offering a surprisingly deep 8-bit representation of the pub sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-jewelry-asia-unl', 'NES', 'Magic Jewelry (Asia) (Unl)', '1990', 'Puzzle', 'Hwang Shinwei', '1', 'Single-screen', 'Falling-block puzzle.', 'Match three or more identical gems to clear the screen.', 'A very popular unlicensed "Columns" clone.', 'Known for its relaxing music and addictive gameplay, it was a staple of many "99 in 1" pirate cartridges during the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-jewelry-2-asia-unl', 'NES', 'Magic Jewelry 2 (Asia) (Unl)', '1991', 'Puzzle', 'Hwang Shinwei', '1', 'Single-screen', 'Falling-block puzzle.', 'Match jewels with updated graphics and new game modes.', 'An unlicensed sequel to the popular gem-matching puzzler.', 'It adds more variety in tile designs and backgrounds, refining the core gameplay loop for fans of the original bootleg title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-john-japan', 'NES', 'Magic John (Japan)', '1990', 'Platform', 'Game Freak', '1', 'Side-scrolling', 'Side-scrolling action.', 'Rescue your friends using magical transformation powers.', 'Known in the West as "Totally Rad."', 'As John, players can transform into different forms (like a bird or a fish) to navigate levels and use elemental magic to defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-johnsons-fast-break-usa', 'NES', 'Magic Johnson''s Fast Break (USA)', '1988', 'Sports', 'Tradewest', '1-2', 'Side view', 'Sports / Basketball.', 'Win basketball games with fast-paced arcade action.', 'A 2-on-2 basketball game endorsed by the NBA legend.', 'It focuses on high-speed play and dunks, offering a simplified but energetic take on the sport that emphasizes quick transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-of-scheherazade-the-usa', 'NES', 'Magic of Scheherazade, The (USA)', '1987', 'Action RPG', 'Culture Brain', '1', 'Top-down/Side-scrolling', 'Action RPG / Turn-based.', 'Travel through time to defeat the wizard Sabaron.', 'A unique hybrid of action-adventure and turn-based combat.', 'It blends "Zelda-style" exploration with traditional RPG battles. Players recruit allies and learn powerful spells across different historical eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-doropie-japan', 'NES', 'Magical Doropie (Japan)', '1990', 'Platform', 'Vic Tokai', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop an evil robot army using various magical shots.', 'A "Mega Man" style action game featuring a witch.', 'Known in the West as "The Krion Conquest," Doropie can select different magic types (fire, ice, etc.) to traverse levels and fight mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-doropie-japan-en-by-video-smash-excellent-v10', 'NES', 'Magical Doropie (Japan) [En by Video Smash Excellent v1.0]', '1990', 'Platform', 'Vic Tokai', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop the robots with fully translated story and menus.', 'The English fan translation of the original Famicom version.', 'Unlike the censored US release, this version restores the original story scenes and dialogue, providing the full 8-bit magical girl narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-mathematics-asia-unl-ntsc', 'NES', 'Magical Mathematics (Asia) (Unl) (NTSC)', '1990', 'Educational', 'Thin Chen Enterprise', '1', 'Single-screen', 'Educational / Puzzle.', 'Solve math problems to progress through magical levels.', 'An unlicensed educational title by Sachen for NTSC systems.', 'It uses a mini-game format to teach basic arithmetic, rewarding correct answers with colorful animations and simple 8-bit puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-mathematics-asia-unl-pal', 'NES', 'Magical Mathematics (Asia) (Unl) (PAL)', '1990', 'Educational', 'Thin Chen Enterprise', '1', 'Single-screen', 'Educational / Puzzle.', 'Solve math problems to progress through magical levels.', 'The PAL region version of the unlicensed math game.', 'Identical to the NTSC version but optimized for European TV standards, ensuring the educational math challenges play at the correct speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-princess-minky-momo---remember-dream-english', 'NES', 'Magical Princess Minky Momo - Remember Dream (English)', '1992', 'Platform/Action', 'Konami', '1', 'Side-scrolling', 'Adventure / Mini-games.', 'Help Minky Momo restore people''s dreams to save Earth.', 'An English fan translation of the anime-based adventure.', 'Players complete various tasks and mini-games based on the popular "Magical Princess" series, with the translation making the story and goals clear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-taruruuto-kun---fantastic-world!!-japan', 'NES', 'Magical Taruruuto Kun - Fantastic World!! (Japan)', '1991', 'Platform', 'Bandai', '1', 'Side-scrolling', 'Side-scrolling action.', 'Navigate through a magical world using Taruruuto''s powers.', 'A vibrant platformer based on the popular manga/anime.', 'Featuring large, colorful sprites, Taruruuto can use his tongue to grab items and enemies, offering a playful and polished late-Famicom experience.');
