INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mari---ayami---luka-no-av-poker-japan-unl', 'NES', 'Mari - Ayami - Luka no AV Poker (Japan) (Unl)', '1992', 'Board Game', 'Unlicensed', '1-4', 'Top-down', 'Card game simulation', 'Win poker matches', 'An adult-themed card game', 'Mari - Ayami - Luka no AV Poker is an unlicensed poker game with risqué themes and traditional card mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mari-street-fighter-iii-turbo-unl', 'NES', 'Mari Street Fighter III Turbo (Unl)', '1997', 'Fighting', 'Unlicensed', '1-2', 'Side view', 'Fighting game', 'Defeat opponents in combat', 'A crossover fighting hack', 'Mari Street Fighter III Turbo is an unlicensed fighting game blending Mario-themed characters with classic fighting mechanics.');
