INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marios-keep-co-op-100', 'NES', 'Mario''s Keep Co-Op 1.00', '2013', 'Platform', 'Fan-made', '1-2', 'Side-scrolling', 'Co-op action platformer', 'Protect the keep together', 'A cooperative Mario hack', 'Mario''s Keep Co-Op is designed for cooperative play, emphasizing teamwork and defense-based gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marusa-no-onna-japan', 'NES', 'Marusa no Onna (Japan)', '1987', 'Board Game', 'Capcom', '1-4', 'Top-down', 'Adventure game', 'Uncover hidden truths', 'A narrative-driven adventure', 'Marusa no Onna is an adventure game inspired by mystery and investigation themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mashin-eiyuu-den-wataru-gaiden-japan', 'NES', 'Mashin Eiyuu Den Wataru Gaiden (Japan)', '1990', 'RPG', 'Hudson Soft', '1', 'Top-down', 'Action RPG', 'Defeat enemies and progress', 'A fantasy action RPG', 'Mashin Eiyuu Den Wataru Gaiden features action-based combat set in a fantasy anime universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mashou-japan', 'NES', 'Mashou (Japan)', '1989', 'Action/Adventure', 'Hudson Soft', '1', 'Top-down', 'Action adventure', 'Survive and defeat monsters', 'A dark fantasy action game', 'Mashou delivers challenging combat and atmospheric stages in a grim fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-chu-&-drunkard-hu---dao-shuai-asia-unl-famicom', 'NES', 'Master Chu & Drunkard Hu - Dao Shuai (Asia) (Unl) (Famicom)', '1989', 'Platform/Puzzle', 'Joy Van', '1', 'Side-scrolling', 'Beat ’em up', 'Fight through enemy groups', 'A martial arts action game', 'Master Chu & Drunkard Hu is a side-scrolling beat ’em up inspired by kung fu cinema.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-chu-&-drunkard-hu-asia-unl-nes', 'NES', 'Master Chu & Drunkard Hu (Asia) (Unl) (NES)', '1989', 'Platform/Puzzle', 'Joy Van', '1', 'Side-scrolling', 'Beat ’em up', 'Fight through enemy groups', 'A martial arts action game', 'The NES version of Master Chu & Drunkard Hu retains the same fast-paced combat and enemy waves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-chu-&-the-drunkard-hu-usa-unl', 'NES', 'Master Chu & The Drunkard Hu (USA) (Unl)', '1989', 'Platform/Puzzle', 'Color Dreams', '1', 'Side-scrolling', 'Beat ’em up', 'Fight through enemy groups', 'A martial arts action game', 'The USA unlicensed release of Master Chu & The Drunkard Hu features identical gameplay with regional differences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-fighter-ii-unl', 'NES', 'Master Fighter II (Unl)', '1991', 'Fighting', 'Unlicensed', '1-2', 'Side view', 'Fighting game', 'Defeat all opponents', 'A competitive fighting game', 'Master Fighter II is an unlicensed one-on-one fighting game inspired by popular arcade fighters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-fighter-vi', 'NES', 'Master Fighter VI''', '1994', 'Fighting', 'Unlicensed', '1-2', 'Side view', '2D Fighting.', 'Defeat a roster of fighters to become the ultimate master.', 'A famous unlicensed 8-bit Street Fighter clone.', 'This bootleg is surprisingly competent, featuring several iconic characters like Ryu and Chun-Li, with special moves that actually work on Famicom hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('masuzoe-youichi---asa-made-famicom-japan', 'NES', 'Masuzoe Youichi - Asa Made Famicom (Japan)', '1986', 'Board Game', 'Coconuts Japan', '1-4', 'Top-down', 'Simulation / Strategy.', 'Discuss politics and solve national issues through dialogue.', 'A unique political simulation game starring Youichi Masuzoe.', 'Players navigate through text-heavy debates and decision-making scenarios, attempting to influence the future of Japan in this very niche 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matendouji-japan', 'NES', 'Matendouji (Japan)', '1990', 'Action', 'Toei Animation', '1', 'Top-down', 'Side-scrolling action.', 'Defeat demons across modern-day Japan to save the world.', 'Known in the West as "Conquest of the Crystal Palace."', 'A highly polished platformer where you use a sword and a loyal dog companion to fight supernatural foes, featuring branching paths and shops.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matsumoto-tooru-no-kabushiki-hisshou-gaku-japan', 'NES', 'Matsumoto Tooru no Kabushiki Hisshou Gaku (Japan)', '1988', 'Simulation', 'Imagineer', '1', 'Menu-based', 'Simulation / Finance.', 'Master the stock market and build a fortune through trading.', 'A serious financial simulation by an investment expert.', 'Players follow real-world stock market trends, analyzing graphs and news reports to buy low and sell high in an attempt to get rich on the Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matsumoto-tooru-no-kabushiki-hisshou-gaku-2-japan', 'NES', 'Matsumoto Tooru no Kabushiki Hisshou Gaku 2 (Japan)', '1989', 'Simulation', 'Imagineer', '1', 'Menu-based', 'Simulation / Finance.', 'Expand your financial empire in this advanced sequel.', 'A deeper and more complex stock market simulator.', 'Featuring more companies and a refined interface, this sequel provides an even more realistic look at the 8-bit world of professional trading and investment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('max-warrior---wakusei-kaigenrei-japan', 'NES', 'Max Warrior - Wakusei Kaigenrei (Japan)', '1991', 'Shoot ''em up', 'KSS', '1', 'Side-scrolling', 'Isometric shooter.', 'Stop an alien invasion in a futuristic world.', 'The Japanese version of the isometric hit "Isolated Warrior."', 'It features incredible pseudo-3D graphics and fast-paced shooting, where the player runs and jumps through visually striking, hazard-filled environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maxi-15-usa-unl', 'NES', 'Maxi 15 (USA) (Unl)', '1988', 'Compilation', 'AVE', '1', 'Various', 'Multi-game.', 'Experience 15 different unlicensed games on one cartridge.', 'A famous multicart by American Video Entertainment (AVE).', 'It contains a mix of puzzles, shooters, and action games like "F-15 City War" and "Krazy Kreatures," showing the diversity of the unlicensed NES market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maxi-15-usa-unl-rev-1', 'NES', 'Maxi 15 (USA) (Unl) (Rev 1)', '1988', 'Compilation', 'AVE', '1', 'Various', 'Multi-game.', 'Experience 15 different unlicensed games with bug fixes.', 'A revised version of the AVE 15-in-1 multicart.', 'This revision improves the menu system and addresses specific loading issues found in some of the included titles for better hardware compatibility.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maxi-15-pack-australia-unl', 'NES', 'Maxi-15 Pack (Australia) (Unl)', '1988', 'Compilation', 'HES', '1', 'Various', 'Multi-game.', 'Explore 15 unique games in this Australian release.', 'The Australian HES version of the Maxi 15 multicart.', 'Distributed in the distinctive HES packaging, it offered Australian gamers a wide variety of unlicensed 8-bit experiences in a single purchase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mcdonaldland-europe', 'NES', 'McDonaldland (Europe)', '1992', 'Platform', 'Virgin Interactive', '1', 'Side-scrolling', 'Side-scrolling platformer.', 'Recover Ronald''s bag and explore the world of McDonaldland.', 'A high-quality platformer known as "M.C. Kids" in the USA.', 'Developed by Virgin, it features creative mechanics like gravity-flipping and complex level design that rivals the best Nintendo-developed titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mcdonaldland-france', 'NES', 'McDonaldland (France)', '1992', 'Platform', 'Virgin Interactive', '1', 'Side-scrolling', 'Side-scrolling platformer.', 'Explore McDonaldland with localized French text.', 'The French version of the polished McDonald''s adventure.', 'It maintains the clever platforming and secret-filled worlds, making the story and tips accessible to French-speaking fans of the brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechanized-attack-usa', 'NES', 'Mechanized Attack (USA)', '1989', 'Action/Shooter', 'SNK', '1-2', 'Top-down', 'First-person shooter.', 'Infiltrate a high-tech island and destroy the cyborg army.', 'An arcade port that supports the NES Zapper.', 'Players fight through waves of robotic enemies in a first-person perspective, with the game occasionally switching to side-scrolling light gun action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-giant-mario-bros', 'NES', 'MEGA GIANT MARIO BROS.', '2012', 'Platform', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Navigate levels as an oversized version of Mario.', 'A famous sprite-modification hack of Super Mario Bros.', 'This hack changes Mario''s size and colors, often increasing his power and changing the physics to create a "giant" experience in the classic 8-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-europe', 'NES', 'Mega Man (Europe)', '1989', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the six Robot Masters and stop Dr. Wily.', 'The PAL version of the legendary Capcom debut.', 'This game introduced the weapon-stealing mechanic and the blue bomber''s iconic platforming, setting the stage for one of gaming''s greatest series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-usa', 'NES', 'Mega Man (USA)', '1987', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the six Robot Masters and stop Dr. Wily.', 'The North American debut of the Blue Bomber.', 'Famous for its "unique" box art, the game itself is a masterclass in challenge and design, allowing players to choose their own level order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-usa-graphic-hack-by-dragonsbrethren-v30-~protoman---the-red-bomber', 'NES', 'Mega Man (USA) [Graphic Hack by Dragonsbrethren v3.0] (~Protoman - The Red Bomber)', '2012', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Play through Mega Man 1 as the mysterious Protoman.', 'A comprehensive graphic hack that replaces the protagonist.', 'This version replaces Mega Man with Protoman, featuring a red color scheme and a shield, giving a fresh look to the original 8-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-usa-hack-by-dragon-eye-studios-v10-~megaman-showdown-i-boss-mode', 'NES', 'Mega Man (USA) [Hack by Dragon Eye Studios v1.0] (~Megaman Showdown I) (Boss Mode)', '2010', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Boss Rush.', 'Fight all the Robot Masters in a continuous gauntlet.', 'A "Boss Mode" hack designed for pure combat practice.', 'Instead of navigating levels, players jump straight into the boss rooms to test their patterns and reflexes against Dr. Wily''s elite machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-usa-hack-by-duelists-v10-~bass', 'NES', 'Mega Man (USA) [Hack by Duelists v1.0] (~Bass)', '2011', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Play through Mega Man 1 as the rival character, Bass.', 'A character hack replacing Mega Man with his later rival.', 'It updates the sprites to depict Bass, offering fans of the series a chance to see how the anti-hero would look in the original 1987 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2---slide-and-charge-shot', 'NES', 'Mega Man 2 - Slide and Charge Shot', '2009', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the eight Robot Masters with modern abilities.', 'A technical hack adding late-series moves to Mega Man 2.', 'This version allows Mega Man to slide and use the "Mega Buster" charge shot in the second game, significantly changing the original game''s balance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-europe', 'NES', 'Mega Man 2 (Europe)', '1989', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop Dr. Wily''s eight new Robot Masters.', 'The PAL release of what many consider the best NES game.', 'Featuring an incredible soundtrack and the addition of E-Tanks and passwords, it refined the Mega Man formula to near perfection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-usa', 'NES', 'Mega Man 2 (USA)', '1988', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop Dr. Wily''s eight new Robot Masters.', 'The definitive North American release of the blue bomber''s peak.', 'This version famously included a "Normal" and "Difficult" mode, making it more accessible to a wider range of players in the West.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-usa-hack-by-blast-hornet-v10-~rockman-exile-ja', 'NES', 'Mega Man 2 (USA) [Hack by Blast Hornet v1.0] (~Rockman Exile) (Ja)', '2010', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Navigate an entirely new and difficult set of levels.', 'A famous and challenging level-hack for Mega Man 2.', 'It features completely redesigned stages, new graphics, and a higher difficulty curve, intended for veterans who have mastered the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-usa-hack-by-infidelity-v10-~mega-man-ultra', 'NES', 'Mega Man 2 (USA) [Hack by Infidelity v1.0] (~Mega Man Ultra)', '2011', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters and Dr. Wily', 'Enhanced Mega Man 2 hack', 'Mega Man Ultra is a gameplay-focused hack of Mega Man 2 that improves physics, visuals, and overall balance for a smoother modern experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-usa-hack-by-sivak-drac-v10-~adventures-of-bass-ii-the', 'NES', 'Mega Man 2 (USA) [Hack by Sivak Drac v1.0] (~Adventures of Bass II, The)', '2012', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Play as Bass and defeat enemies', 'A character-focused Mega Man hack', 'The Adventures of Bass II reimagines Mega Man 2 by introducing Bass as the main playable character with unique abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-usa-hack-by-tokkan-kouzi-kanrinin-v10-~mega-man-neo', 'NES', 'Mega Man 2 (USA) [Hack by Tokkan Kouzi Kanrinin v1.0] (~Mega Man Neo)', '2011', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters in remixed stages', 'A reworked Mega Man 2 hack', 'Mega Man Neo offers redesigned levels, enemies, and balance changes while keeping the core Mega Man 2 structure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-randomizer', 'NES', 'Mega Man 2 Randomizer', '2014', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Complete randomized stages', 'A randomizer modification', 'Mega Man 2 Randomizer shuffles stages, items, and bosses to create a new experience every playthrough.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-2-revamped', 'NES', 'Mega Man 2 Revamped', '2015', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters with improvements', 'A polished enhancement hack', 'Mega Man 2 Revamped refines level design, visuals, and mechanics while staying faithful to the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-europe', 'NES', 'Mega Man 3 (Europe)', '1990', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A classic NES action game', 'Mega Man 3 expands the series with new weapons, sliding mechanics, and challenging robot masters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-europe-rev-a', 'NES', 'Mega Man 3 (Europe) (Rev A)', '1990', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A revised European release', 'The Rev A version of Mega Man 3 includes minor fixes and adjustments to the original release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-usa', 'NES', 'Mega Man 3 (USA)', '1990', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A definitive NES action classic', 'The USA version of Mega Man 3 delivers fast-paced platforming with iconic bosses and weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-usa-beta', 'NES', 'Mega Man 3 (USA) (Beta)', '1990', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Test unfinished content', 'A prototype version', 'Mega Man 3 Beta showcases unused content, early level designs, and developmental differences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-improvement', 'NES', 'Mega Man 3 Improvement', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters with refinements', 'An improvement-focused hack', 'Mega Man 3 Improvement enhances gameplay balance, visuals, and minor mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-3-revamped', 'NES', 'Mega Man 3 Revamped', '2015', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters in redesigned stages', 'A modernized Mega Man 3 hack', 'Mega Man 3 Revamped offers reworked levels and improved flow while retaining the original game’s identity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4---free-of-charge', 'NES', 'Mega Man 4 - Free of Charge', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Action platformer', 'Complete the game without paying', 'Easter-themed Mega Man hack', 'Mega Man 4 - Free of Charge is a novelty hack offering humorous changes and altered progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4-europe', 'NES', 'Mega Man 4 (Europe)', '1992', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A classic NES sequel', 'Mega Man 4 introduces new weapons, charge shots, and refined gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4-usa', 'NES', 'Mega Man 4 (USA)', '1991', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A localized USA release', 'The USA version of Mega Man 4 delivers the same polished action platforming with regional adjustments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4-usa-rev-a', 'NES', 'Mega Man 4 (USA) (Rev A)', '1991', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Action platformer', 'Defeat Robot Masters', 'A revised release version', 'Mega Man 4 Rev A includes small fixes and optimizations over the original version.');
