INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4-usa-hack-by-mickevincent-v10-~mega-man---maverick-revenge', 'NES', 'Mega Man 4 (USA) [Hack by Mickevincent v1.0] (~Mega Man - Maverick Revenge)', '2012', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat a new set of Robot Masters in this total conversion.', 'A massive hack of Mega Man 4 with new levels and bosses.', 'This project completely redesigns the stages and boss patterns of the 4th entry, offering a fresh and challenging experience for series veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-4-voyage', 'NES', 'Mega Man 4 Voyage', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Complete a world-traveling adventure with new mechanics.', 'A sophisticated hack of MM4 with high-quality level design.', 'Known for its creative use of the game engine, it features entirely new stages, custom music, and a polished difficulty curve that feels like an official sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-5-europe', 'NES', 'Mega Man 5 (Europe)', '1993', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop Proto Man''s rogue army and clear his name.', 'The PAL version of the fifth Blue Bomber adventure.', 'Introducing "Beat" the robotic bird and the "Mega Tank," this entry offers some of the most vibrant and colorful graphics on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-5-usa', 'NES', 'Mega Man 5 (USA)', '1992', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop Proto Man''s rogue army and clear his name.', 'The North American release of the 5th Mega Man title.', 'Players must track down the mysterious "Dark Men" and uncover the truth behind Proto Man''s sudden turn to the dark side.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-5:-protoman-edition', 'NES', 'Mega Man 5: Protoman Edition', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Play through the entire game as Proto Man with his shield.', 'A character hack that makes Proto Man the protagonist.', 'Unlike the original where he is an NPC, here you control him directly, utilizing his iconic shield to deflect bullets and a unique charge shot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-5:-second-strike-protoman-edition', 'NES', 'Mega Man 5: Second Strike Protoman Edition', '2014', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Experience a harder Proto Man quest with new challenges.', 'An enhanced version of the Proto Man Edition hack.', 'It features adjusted difficulty, different color palettes, and minor level tweaks to better suit Proto Man''s defensive playstyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-6-usa', 'NES', 'Mega Man 6 (USA)', '1993', 'Platform/Action', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Win the World Robot Alliance tournament and defeat Mr. X.', 'The final official Mega Man release on the NES.', 'It introduced the "Rush Adaptors," allowing Mega Man to fuse with his dog to fly or punch through blocks, featuring a high level of technical polish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-6-usa-hack-by-dragon-eye-studios-v10-~megaman-showdown-vi-boss-mode', 'NES', 'Mega Man 6 (USA) [Hack by Dragon Eye Studios v1.0] (~Megaman Showdown VI) (Boss Mode)', '2011', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Boss Rush.', 'Fight all the Robot Masters of Mega Man 6 in a row.', 'A specialized "Boss Mode" hack for practicing combat.', 'It removes the platforming stages, letting players focus entirely on mastering the patterns of the 8 World Robot Masters and Mr. X.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-iii-ultimate', 'NES', 'Mega Man III Ultimate', '2014', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Experience the best of MM3 with balance and visual fixes.', 'A definitive "enhancement" hack of the third game.', 'It addresses slowdown issues, polishes graphics, and adds minor quality-of-life improvements while keeping the legendary core gameplay intact.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-remastered', 'NES', 'Mega Man Remastered', '2012', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Relive the original adventure with updated 8-bit assets.', 'A graphical and technical overhaul of the first Mega Man.', 'It replaces sprites and backgrounds with more detailed versions, often borrowing assets from later games to make the 1987 debut look modern.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-1---the-new-lands-remastered', 'NES', 'Megaman 1 - The New Lands Remastered', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Explore entirely new worlds in the original game''s engine.', 'A total level conversion of the first Mega Man game.', 'This "Remastered" hack provides a brand new quest with unique stage layouts, requiring players to relearn their strategies for the original six bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-in-the-mushroom-kingdom', 'NES', 'Megaman in the Mushroom Kingdom', '2011', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Fight through Mario''s world as the Blue Bomber.', 'A crossover hack putting Mega Man in Super Mario stages.', 'Featuring Mario-themed enemies and environments, it''s a surreal mashup that blends Capcom combat with Nintendo''s iconic level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman:-super---16-bit-graphics', 'NES', 'Megaman: Super - 16-bit Graphics', '2013', 'Platform/Action', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Play the 8-bit game with 16-bit style color and sprites.', 'A visual hack mimicking the "Mega Man Powered Up" or SNES look.', 'It pushes the NES color palette to its limit to replicate the look of the Super Nintendo entries, making the classic game feel like a 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megamari', 'NES', 'MegaMari', '2009', 'Platform', 'Fan-made', '1', 'Side-scrolling', 'Side-scrolling action.', 'Navigate a Mega Man-style world with Touhou characters.', 'A fan-made "demake" or crossover based on the Touhou series.', 'It blends the bullet-hell elements of Touhou Project with the platforming mechanics of Mega Man, featuring Marisa Kirisame as the lead.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mei-guo-fu-hao---american-man-china-unl', 'NES', 'Mei Guo Fu Hao - American Man (China) (Unl)', '1991', 'Platform', 'Unlicensed', '1', 'Side-scrolling', 'Board Game / Strategy.', 'Become the richest man in America through real estate.', 'An unlicensed Chinese "Monopoly" clone.', 'Featuring digitized photos and caricatures of American life, it’s a typical Asian bootleg board game focusing on property buying and financial luck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meiji-ishin-japan', 'NES', 'Meiji Ishin (Japan)', '1989', 'Strategy', 'Epoch', '1', 'Top-down', 'Strategy / RPG.', 'Play a role in the political revolution of the Meiji era.', 'A historical simulation set during Japan''s transition to modernity.', 'Players interact with historical figures and make decisions that influence the social and military future of 19th-century Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meikyuu-jima-japan', 'NES', 'Meikyuu Jima (Japan)', '1987', 'Action/Adventure', 'Capcom', '1', 'Side-scrolling', 'Puzzle.', 'Push blocks to clear paths and find the exit in each level.', 'Known in the West as "Kickle Cubicle."', 'As Kickle, you create ice blocks to bridge gaps and trap enemies. It''s a highly regarded and colorful puzzle game with smooth mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meikyuu-kumikyoku-milon-no-daibouken-japan', 'NES', 'Meikyuu Kumikyoku Milon no Daibouken (Japan)', '1988', 'Platform/Adventure', 'Hudson Soft', '1', 'Side-scrolling', 'Action / Platformer.', 'Find secret items and hidden rooms in the massive castle.', 'Known in the West as "Milon''s Secret Castle."', 'Famous for its cryptic secrets, players shoot bubbles to reveal hidden items and must solve bizarre environmental puzzles to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meimon!-dai-san-yakyuu-bu-japan', 'NES', 'Meimon! Dai San Yakyuu Bu (Japan)', '1990', 'Sports', 'Capcom', '1-2', 'Side view', 'Sports / Baseball.', 'Lead the "Third Baseball Club" to a championship victory.', 'A baseball game based on a popular sports manga.', 'It features a story mode with character-specific drama and special moves, differentiating it from more traditional 8-bit baseball simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meimon!-takonishi-ouendan---kouha-6-nin-shuu-japan', 'NES', 'Meimon! Takonishi Ouendan - Kouha 6 Nin Shuu (Japan)', '1990', 'Adventure', 'Tose', '1', 'Side-scrolling', 'Simulation / Strategy.', 'Manage an "Ouendan" (cheerleading squad) to support teams.', 'A unique game focusing on the world of Japanese school spirit.', 'Players manage a group of "tough guys" who perform elaborate cheers, blending social simulation with rhythmic and strategic elements.');
