INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-usa-hack-by-vandal-v050-~metroid---eternal-darkness', 'NES', 'Metroid (USA) [Hack by Vandal v0.50] (~Metroid - Eternal Darkness)', '2011', 'Action/Adventure', 'Fan-made', '1', 'Side-scrolling', 'Action adventure', 'Explore darker content', 'A darker-themed hack', 'Metroid - Eternal Darkness introduces horror elements and increased difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-automap', 'NES', 'Metroid Automap', '2015', 'Action/Adventure', 'Fan-made', '1', 'Side-scrolling', 'Action adventure', 'Navigate with a map', 'A utility modification', 'Metroid Automap adds an in-game map system to assist exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-mother', 'NES', 'Metroid mOTHER', '2016', 'Action/Adventure', 'Fan-made', '1', 'Side-scrolling', 'Action adventure', 'Crossover exploration', 'A crossover fan hack', 'Metroid mOTHER blends elements from Metroid and EarthBound for a unique experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-walljump', 'NES', 'Metroid Walljump', '2014', 'Action/Adventure', 'Fan-made', '1', 'Side-scrolling', 'Action / Exploration.', 'Explore Zebes with the new ability to jump off walls.', 'A technical hack for the original Metroid.', 'This modification allows Samus to perform a wall jump, drastically changing how players navigate the planet and opening up new sequence-breaking possibilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase-pachi-pro---pachio-kun-japan', 'NES', 'Mezase Pachi Pro - Pachio Kun (Japan)', '1990', 'Board Game', 'Coconuts Japan', '1-4', 'Top-down', 'Simulation / Pachinko.', 'Win big at the parlors to help the round-headed Pachio.', 'A charming Pachinko simulation starring a mascot character.', 'Players manage their balls and adjust the strength of their shots across various themed machines in an attempt to hit the jackpot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase-top-pro---green-ni-kakeru-yume-japan', 'NES', 'Mezase Top Pro - Green ni Kakeru Yume (Japan)', '1989', 'Sports', 'Jaleco', '1', 'Top-down', 'Sports / Golf.', 'Climb the professional rankings to become a golf legend.', 'A realistic and detailed golf sim for the Famicom.', 'Featuring deep mechanics for wind, club selection, and green slope, it aims to provide a professional-level golfing experience on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-andrettis-world-gp-usa', 'NES', 'Michael Andretti''s World GP (USA)', '1988', 'Racing', 'American Sammy', '1', 'Top-down', 'Sports / Racing.', 'Win the Formula One World Championship across 16 tracks.', 'A fast-paced F1 racing game endorsed by Michael Andretti.', 'Players can customize their car''s settings and must master manual or automatic shifting to beat international rivals in high-speed circuit racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania-7-unl', 'NES', 'Mickey Mania 7 (Unl)', '1998', 'Platform', 'Unlicensed', '1', 'Side-scrolling', 'Side-scrolling action.', 'Help Mickey navigate through levels based on his cartoons.', 'An unlicensed 8-bit demake of the 16-bit Mickey Mania.', 'This bootleg attempts to replicate the visuals and stages of the SNES/Genesis original, featuring surprisingly large sprites for the NES hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse---dream-balloon-usa-proto', 'NES', 'Mickey Mouse - Dream Balloon (USA) (Proto)', '1992', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Use balloons to navigate levels and rescue friends.', 'An unreleased US prototype of Mickey Mouse 3.', 'A fascinating look at the planned Western release of the third Mickey game, featuring polished platforming and creative balloon-based mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-japan', 'NES', 'Mickey Mouse (Japan)', '1989', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Help Mickey rescue Minnie from the witch''s castle.', 'Known in the West as "Mickey Mousecapade."', 'This is the original Japanese release (published by Hudson Soft), featuring Mickey and Minnie navigating together through diverse, puzzle-filled stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-3---yume-fuusen-japan', 'NES', 'Mickey Mouse 3 - Yume Fuusen (Japan)', '1992', 'Platform', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Travel through dreams using magical balloons to find Minnie.', 'The Japanese version of what would become "Kid Klown."', 'Mickey uses balloons as weapons and tools in a vibrant, high-quality platformer that was later re-skinned for its Western release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mousecapade-usa', 'NES', 'Mickey Mousecapade (USA)', '1988', 'Platform', 'Capcom', '1-2', 'Side-scrolling', 'Side-scrolling action.', 'Lead Mickey and Minnie to safety through dangerous worlds.', 'A classic Capcom-developed Disney adventure for the NES.', 'Players must protect Minnie while fighting enemies. It features unique levels like the Ocean, the Forest, and a giant dollhouse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-adventure-in-numberland-usa', 'NES', 'Mickey''s Adventure in Numberland (USA)', '1994', 'Educational', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Educational / Puzzle.', 'Collect numbers and solve math problems in a Disney world.', 'A fun educational game designed for younger children.', 'Mickey travels through colorful stages where the goal is to learn basic counting and arithmetic in a friendly, low-stress environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-safari-in-letterland-usa', 'NES', 'Mickey''s Safari in Letterland (USA)', '1993', 'Educational', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Educational / Puzzle.', 'Explore the world to find letters and learn the alphabet.', 'A Disney educational title focused on literacy skills.', 'Players help Mickey travel via jeep and plane to collect letters, making it an engaging tool for early childhood education.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-usa-unl', 'NES', 'Micro Machines (USA) (Unl)', '1991', 'Racing', 'Codemasters', '1-4', 'Top-down', 'Racing.', 'Win races on kitchen tables, desks, and garden paths.', 'A technical masterpiece by Codemasters using miniature cars.', 'Famous for its tiny sprites and incredibly smooth scrolling, it offers high-speed competitive racing in everyday household environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('middle-school-english---dong-dong-nao-ii-asia-unl', 'NES', 'Middle School English - Dong Dong Nao II (Asia) (Unl)', '1991', 'Educational', 'Unlicensed', '1', 'Menu-based', 'Educational.', 'Solve English language puzzles to progress.', 'An unlicensed Asian educational game.', 'Part of the "Dong Dong Nao" series, it uses simple mini-games to teach English vocabulary and grammar to Famicom users.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mig-29---soviet-fighter-usa-unl', 'NES', 'MiG 29 - Soviet Fighter (USA) (Unl)', '1989', 'Shoot ''em up', 'Camerica', '1', 'Third-person', 'Combat Flight Sim.', 'Complete dangerous missions flying the Soviet MiG-29.', 'An unlicensed flight simulator by Camerica.', 'Players take a first-person view from the cockpit, engaging in dogfights and bombing runs across multiple high-stakes military scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic---secret-of-the-inner-sanctum-usa', 'NES', 'Might and Magic - Secret of the Inner Sanctum (USA)', '1990', 'RPG', 'American Sammy', '1', 'Top-down', 'Turn-based RPG.', 'Explore the world of Varn and uncover its deep secrets.', 'A massive Western RPG ported to the NES.', 'Featuring a first-person dungeon crawling perspective, it offers a huge world, hundreds of items, and deep party customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic-japan', 'NES', 'Might and Magic (Japan)', '1991', 'RPG', 'Tokuma Shoten', '1', 'Top-down', 'Turn-based RPG.', 'Explore the world of Varn with localized text.', 'The Japanese Famicom version of the classic PC RPG.', 'This version features revised graphics and a different musical score compared to the US release, catering to Japanese RPG tastes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-bomb-jack-europe', 'NES', 'Mighty Bomb Jack (Europe)', '1987', 'Platform/Action', 'Tecmo', '1', 'Side-scrolling', 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'A fast-paced, high-jumping sequel to the arcade original.', 'Known for its unique physics where Jack can jump incredibly high and "float," it requires precise timing to collect all bombs in the correct order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-bomb-jack-japan', 'NES', 'Mighty Bomb Jack (Japan)', '1986', 'Platform/Action', 'Tecmo', '1', 'Side-scrolling', 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'The original Famicom release of the bomb-collecting hit.', 'Featuring many hidden secrets and alternative paths, it is a challenging platformer that rewards exploration and mastery of Jack''s jumping mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-bomb-jack-usa', 'NES', 'Mighty Bomb Jack (USA)', '1987', 'Platform/Action', 'Tecmo', '1', 'Side-scrolling', 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'The North American release of the frantic Tecmo platformer.', 'Jack must navigate treacherous rooms filled with enemies, collecting treasure and power-ups to survive the massive 8-bit pyramid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-final-fight-europe', 'NES', 'Mighty Final Fight (Europe)', '1993', 'Beat ''em up', 'Capcom', '1-2', 'Side-scrolling', 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'A brilliant 8-bit reimagining of the arcade classic.', 'It features an RPG-like leveling system and a "chibi" art style, offering one of the most polished brawler experiences on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-final-fight-japan', 'NES', 'Mighty Final Fight (Japan)', '1993', 'Beat ''em up', 'Capcom', '1-2', 'Side-scrolling', 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'The original Japanese release of the "Mighty" brawler.', 'Known for its humor and tight combat, players can choose between Cody, Guy, and Haggar, each with unique special moves and leveling paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-final-fight-usa', 'NES', 'Mighty Final Fight (USA)', '1993', 'Beat ''em up', 'Capcom', '1-2', 'Side-scrolling', 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'A brilliant 8-bit reimagining of the arcade classic.', 'It features an RPG-like leveling system and a "chibi" art style, offering one of the most polished brawler experiences on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mike-tysons-punch-out!!-europe', 'NES', 'Mike Tyson''s Punch-Out!! (Europe)', '1987', 'Sports/Boxing', 'Nintendo', '1', 'Side view', 'Sports / Boxing.', 'Rise through the ranks to face the champion Mike Tyson.', 'One of the most iconic and polished sports games ever made.', 'Players control Little Mac, using timing and pattern recognition to defeat a cast of eccentric boxers in a quest for the world title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mike-tysons-punch-out!!-europe-rev-a', 'NES', 'Mike Tyson''s Punch-Out!! (Europe) (Rev A)', '1987', 'Sports/Boxing', 'Nintendo', '1', 'Side view', 'Sports / Boxing.', 'Defeat Mike Tyson with minor technical optimizations.', 'A revised PAL release of the legendary boxing title.', 'This revision ensures better performance on European hardware, maintaining the tight controls and iconic character animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mike-tysons-punch-out!!-usa', 'NES', 'Mike Tyson''s Punch-Out!! (USA)', '1987', 'Sports/Boxing', 'Nintendo', '1', 'Side view', 'Sports / Boxing.', 'Rise through the ranks to face the champion Mike Tyson.', 'The definitive North American boxing masterpiece.', 'Featuring the likeness of Mike Tyson as the final boss, it is a game of skill and memory that remains a benchmark for the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mike-tysons-punch-out!!-usa-rev-a', 'NES', 'Mike Tyson''s Punch-Out!! (USA) (Rev A)', '1987', 'Sports/Boxing', 'Nintendo', '1', 'Side view', 'Sports / Boxing.', 'Face Mike Tyson with corrected text and bug fixes.', 'A revised US release of the classic boxing game.', 'This update addresses minor textual errors in the trainers'' advice and ensures maximum compatibility with NES hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('millionaire-asia-unl-nes', 'NES', 'Millionaire (Asia) (Unl) (NES)', '1990', 'Board Game', 'Unlicensed', '1-4', 'Top-down', 'Quiz / Trivia.', 'Answer questions correctly to win a virtual million.', 'An unlicensed 8-bit take on "Who Wants to Be a Millionaire."', 'Testing the player''s general knowledge, it follows the famous TV show format with lifelines and increasing stakes for each question.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('millipede-japan', 'NES', 'Millipede (Japan)', '1988', 'Action/Shooter', 'HAL Laboratory', '1-2', 'Vertical scrolling', 'Fixed shooter.', 'Shoot the invading millipedes and insects to survive.', 'The Famicom port of the high-speed Atari arcade sequel.', 'Faster and more chaotic than Centipede, it introduces new enemies like bees and dragonflies, requiring quick reflexes to protect your garden.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('millipede-usa', 'NES', 'Millipede (USA)', '1988', 'Action/Shooter', 'HAL Laboratory', '1-2', 'Vertical scrolling', 'Fixed shooter.', 'Shoot the invading millipedes and insects to survive.', 'A frantic and colorful arcade port for the NES.', 'Players must clear the screen of various bugs while navigating a mushroom-filled field, offering classic "golden age" arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('milons-secret-castle-usa', 'NES', 'Milon''s Secret Castle (USA)', '1988', 'Platform/Adventure', 'Hudson Soft', '1', 'Side-scrolling', 'Side-scrolling action.', 'Find the hidden music boxes to rescue the Queen.', 'A cryptic and challenging Hudson Soft adventure.', 'Famous for its "bubbles" weapon and hidden items, it requires players to search every block for secrets to progress through the castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-blower-pak-australia-unl', 'NES', 'Mind Blower Pak (Australia) (Unl)', '1988', 'Compilation', 'HES', '1', 'Various', 'Multi-game.', 'Experience various unlicensed games in one cartridge.', 'An Australian HES multicart featuring several unique titles.', 'It offered a budget-friendly way for gamers to play a variety of action and puzzle games outside of Nintendo''s official ecosystem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mindseeker-japan', 'NES', 'Mindseeker (Japan)', '1987', 'Board Game', 'Namco', '1-4', 'Top-down', 'Simulation / Experimental.', 'Develop your "Psychic Powers" through various tests.', 'A bizarre and infamous game about ESP training.', 'Created by Namco, it asks players to guess cards and perform "mental" tasks, supposedly measuring and training their real-world psychic abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minelvaton-saga-japan', 'NES', 'Minelvaton Saga (Japan)', '1987', 'RPG', 'Taito', '1', 'Top-down', 'Turn-based RPG.', 'Stop the dark god from destroying the kingdom of Minelvaton.', 'A beautiful and overlooked RPG with a unique combat view.', 'It features large sprites during battles and an epic story, representing the high quality of early Japanese exclusive role-playing games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-putt-japan', 'NES', 'Mini Putt (Japan)', '1987', 'Sports', 'Togo', '1-2', 'Top-down', 'Sports / Golf.', 'Master the art of miniature golf across creative courses.', 'A fun and accessible take on mini-golf.', 'Players must navigate windmills, ramps, and water hazards, focusing on power and aim to get a hole-in-one in this lighthearted sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-putt-japan-en-by-no-talent-v10', 'NES', 'Mini Putt (Japan) [En by No Talent v1.0]', '1987', 'Sports', 'Togo', '1-2', 'Top-down', 'Sports / Golf.', 'Play mini-golf with fully translated English menus.', 'The English fan translation of the Famicom Mini Putt.', 'This version makes the course descriptions and scoring systems clear for Western players, allowing for a smooth competitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-taabou-no-nakayoshi-daisakusen-japan', 'NES', 'Minna no Taabou no Nakayoshi Daisakusen (Japan)', '1991', 'Platform/Puzzle', 'Character Soft', '1', 'Side-scrolling', 'Puzzle strategy', 'Complete tactical challenges', 'A cute strategy puzzle game', 'Minna no Taabou no Nakayoshi Daisakusen features lighthearted tactical puzzles starring Sanrio’s Tabo character.');
