INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mississippi-satsujin-jiken-japan', 'NES', 'Mississippi Satsujin Jiken (Japan)', '1986', 'Adventure', 'Jaleco', '1', 'Side-scrolling', 'Adventure investigation', 'Solve a murder mystery', 'A detective adventure game', 'Mississippi Satsujin Jiken is a story-driven mystery involving investigation and deduction.');
