INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mito-koumon---sekai-manyuu-ki-japan', 'NES', 'Mito Koumon - Sekai Manyuu Ki (Japan)', '1990', 'Action/Adventure', 'Sunsoft', '1', 'Top-down', 'Adventure RPG', 'Explore historical Japan', 'A historical adventure game', 'Mito Koumon - Sekai Manyuu Ki follows episodic adventures inspired by Japanese folklore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mito-koumon-japan', 'NES', 'Mito Koumon (Japan)', '1987', 'Action/Adventure', 'Sunsoft', '1', 'Top-down', 'Adventure RPG', 'Explore historical Japan', 'A historical adventure game', 'Mito Koumon features narrative-driven exploration and traditional Japanese themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mitsume-ga-tooru-japan', 'NES', 'Mitsume ga Tooru (Japan)', '1992', 'RPG', 'Tomy', '1', 'Top-down', 'Action platformer', 'Defeat demons', 'A mythological action game', 'Mitsume ga Tooru is a side-scrolling action platformer based on Japanese supernatural folklore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mitsume-ga-tooru-japan-en-by-spoony-bard-v101', 'NES', 'Mitsume ga Tooru (Japan) [En by Spoony Bard v1.01]', '1992', 'RPG', 'Tomy', '1', 'Top-down', 'Side-scrolling action.', 'Stop the ancient Prince Sharaku using mystical powers.', 'A top-tier platformer based on the "Three-Eyed One" manga.', 'Players use a "Red Condor" spear as both a weapon and a platform. This translation lets you follow the story of Sharaku’s quest to prevent the end of the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mixed-up-mario-bros', 'NES', 'Mixed Up Mario Bros.', '2012', 'Platform', 'Fan-made', '1-2', 'Single-screen', 'Side-scrolling action.', 'Navigate weird, scrambled levels in this Mario hack.', 'A creative "remix" hack of the original Super Mario Bros.', 'This version swaps tile-sets and enemy placements to create a surreal, dream-like experience for players who have memorized the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mizushima-shinji-no-dai-koushien-japan', 'NES', 'Mizushima Shinji no Dai Koushien (Japan)', '1989', 'Sports', 'Capcom', '1-2', 'Side view', 'Sports / Baseball.', 'Lead your team to victory in this manga-based baseball sim.', 'A sports title featuring characters from famous baseball manga.', 'It focuses on a cinematic story mode and special player abilities, capturing the high-drama style of Shinji Mizushima’s legendary illustrations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moai-kun-japan', 'NES', 'Moai Kun (Japan)', '1990', 'Puzzle/Action', 'Konami', '1', 'Single-screen', 'Puzzle / Platformer.', 'Rescue your friends and reach the exit by headbutting blocks.', 'A clever and cute logic-based puzzle game by Konami.', 'Players control a Moai statue that must solve single-screen puzzles by manipulating blocks and avoiding traps, all while looking for its kidnapped companions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moai-kun-japan-en-by-suicidal-v10', 'NES', 'Moai Kun (Japan) [En by Suicidal v1.0]', '1990', 'Puzzle/Action', 'Konami', '1', 'Single-screen', 'Puzzle / Platformer.', 'Solve the Moai puzzles with fully translated text.', 'The English fan translation of Konami''s Moai-themed puzzler.', 'This version translates the stage titles and menu hints, making the increasingly difficult logic puzzles easy to navigate for Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mobile-suit-z-gundam---hot-scramble-japan', 'NES', 'Mobile Suit Z Gundam - Hot Scramble (Japan)', '1986', 'Shoot ''em up', 'Bandai', '1', 'Side-scrolling', '3D Shooter / Action.', 'Destroy the Axis forces using the Zeta Gundam''s power.', 'A dual-genre Gundam title featuring 3D cockpit segments.', 'Designed partly by Masanobu Endo (of Xevious fame), it mixes first-person space combat with side-scrolling base infiltration levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moe-pro!---saikyou-hen-japan', 'NES', 'Moe Pro! - Saikyou Hen (Japan)', '1989', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Win the championship with the "Strongest" version of the pro league.', 'An enhanced entry in the popular Moero!! Pro Yakyuu series.', 'It features updated rosters and improved digitized voices, which were a hallmark of the Jaleco sports games on the Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moe-pro!-90---kandou-hen-japan', 'NES', 'Moe Pro! ''90 - Kandou Hen (Japan)', '1990', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Experience the 1990 pro season with "Kandou" (emotion).', 'A refined baseball sim focusing on the drama of the sport.', 'This 1990 update added more player animations and emotional reactions to home runs and strikeouts, adding flair to the standard 8-bit gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero-twinbee---cinnamon-hakase-wo-sukue!-japan', 'NES', 'Moero TwinBee - Cinnamon Hakase wo Sukue! (Japan)', '1993', 'Shoot ''em up', 'Konami', '1-2', 'Vertical scrolling', 'Vertical shoot ''em up.', 'Rescue Dr. Cinnamon in this cute-em-up adventure.', 'Known in the West as "Stinger."', 'Unlike the first game, this sequel features both vertical and horizontal scrolling stages and supports three-player co-op with the right adapter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-junior-basket---two-on-two-japan', 'NES', 'Moero!! Junior Basket - Two on Two (Japan)', '1988', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Basketball.', 'Outscore your rivals in street-style 2-on-2 matches.', 'A fast-paced arcade basketball game with a youth focus.', 'Featuring exaggerated jumps and quick gameplay, it offers a fun, simplified take on the sport compared to more complex simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-juudou-warriors-japan', 'NES', 'Moero!! Juudou Warriors (Japan)', '1990', 'Sports/Fighting', 'Jaleco', '1-2', 'Side view', 'Fighting / Sports.', 'Master Judo techniques to win the global tournament.', 'A rare 8-bit simulation of the martial art of Judo.', 'Players must time their throws and counters precisely, moving through a tournament structure to become the world champion of the tatami.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-soccer-japan', 'NES', 'Moero!! Pro Soccer (Japan)', '1988', 'Sports', 'Jaleco', '1-2', 'Top-down', 'Sports / Soccer.', 'Lead your national team to the 8-bit World Cup title.', 'A soccer game known for its cinematic penalty shootouts.', 'It features large character sprites and uses digitized voice samples for the referee, giving it a distinct "arcade" feel for a home console title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-tennis-japan', 'NES', 'Moero!! Pro Tennis (Japan)', '1988', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Tennis.', 'Win the grand slam across different court surfaces.', 'A solid 8-bit tennis sim with a behind-the-player view.', 'It offers a variety of players with different stats and requires careful positioning to execute powerful serves and volleys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-yakyuu-88---ketteiban-japan', 'NES', 'Moero!! Pro Yakyuu ''88 - Ketteiban (Japan)', '1988', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Compete in the 1988 pro season with definitive rosters.', 'The "Ketteiban" (Definitive) 1988 update of Jaleco''s baseball.', 'It fixed many of the balancing issues of the previous year and updated all team stats for the most accurate 8-bit baseball experience of ''88.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-yakyuu-japan', 'NES', 'Moero!! Pro Yakyuu (Japan)', '1987', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Win the league in this pioneering sports title.', 'Known in the West as "Bases Loaded."', 'Famous for its TV-style broadcast perspective and digitized voices, it set the standard for how baseball games looked on the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-yakyuu-japan-rev-1', 'NES', 'Moero!! Pro Yakyuu (Japan) (Rev 1)', '1987', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Win the league with minor graphical fixes.', 'A revised release of the original Jaleco baseball game.', 'This version corrected some player name typos and addressed a few sprite-flicker issues during the cinematic home-run sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!!-pro-yakyuu-japan-rev-2', 'NES', 'Moero!! Pro Yakyuu (Japan) (Rev 2)', '1987', 'Sports', 'Jaleco', '1-2', 'Side view', 'Sports / Baseball.', 'Win the league with optimized AI and bug fixes.', 'The third production run of the first Moero!! title.', 'This revision includes the most stable code, addressing rare crashing bugs and perfecting the AI''s pitching logic for a fairer challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moeru!-oniisan-japan', 'NES', 'Moeru! Oniisan (Japan)', '1990', 'Action', 'ASCII', '1', 'Side-scrolling', 'Side-scrolling action.', 'Rescue your sister and defeat the gang of weirdos.', 'An action game based on a comedy manga/anime series.', 'It features bizarre humor and varied levels where the "Burning Brother" must fight through schools and streets in a quirky 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-densetsu-japan', 'NES', 'Momotarou Densetsu (Japan)', '1987', 'RPG', 'Hudson Soft', '1', 'Top-down', 'Turn-based RPG.', 'Defeat the King of the Oni as the legendary Momotarou.', 'The first entry in the massive Hudson Soft RPG series.', 'Based on Japanese folklore, players recruit a dog, a monkey, and a pheasant to fight demons in a world filled with charm and humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-densetsu-gaiden-japan', 'NES', 'Momotarou Densetsu Gaiden (Japan)', '1993', 'RPG', 'Hudson Soft', '1', 'Top-down', 'Turn-based RPG.', 'Complete side stories featuring Momotarou''s companions.', 'A collection of shorter RPG adventures within the same world.', 'It focuses on the backstories of the supporting cast, offering a more episodic structure compared to the main quest of the first game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu-japan', 'NES', 'Momotarou Dentetsu (Japan)', '1988', 'Board Game', 'Hudson Soft', '1-4', 'Top-down', 'Board Game / Strategy.', 'Become the top railroad mogul by traveling across Japan.', 'The debut of the legendary "railroad" board game series.', 'Players travel by train, buying properties and avoiding the "God of Poverty," in what became one of Japan''s most beloved multiplayer franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('money-game-2---kabutochou-no-kiseki-the-japan', 'NES', 'Money Game 2 - Kabutochou no Kiseki, The (Japan)', '1992', 'Simulation', 'Sofel', '1', 'Menu-based', 'Simulation / Finance.', 'Build a financial empire on the Tokyo Stock Exchange.', 'A deep and complex stock market simulator.', 'It features more realistic market fluctuations and expanded investment options compared to the first game, catering to the "economic bubble" era of Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('money-game-the-japan', 'NES', 'Money Game, The (Japan)', '1989', 'Simulation', 'Sofel', '1', 'Menu-based', 'Simulation / Finance.', 'Invest wisely and manage your portfolio to get rich.', 'The first 8-bit stock trading simulation for the Famicom.', 'Players analyze news and charts to make trades, aiming to turn a small investment into a fortune in this unique financial "game."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-france', 'NES', 'Monopoly (France)', '1992', 'Board Game', 'Sculptured Software', '1-8', 'Top-down', 'Board Game / Strategy.', 'Buy properties and bankrupt your rivals to win.', 'The French-language version of the world-famous board game.', 'It features the iconic Paris street names and fully translated chance/community chest cards for a localized 8-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-germany', 'NES', 'Monopoly (Germany)', '1992', 'Board Game', 'Sculptured Software', '1-8', 'Top-down', 'Board Game / Strategy.', 'Buy properties and bankrupt your rivals to win.', 'The German-language version of the world-famous board game.', 'All property names and rules are translated into German, allowing fans in the region to enjoy the classic real estate strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-japan', 'NES', 'Monopoly (Japan)', '1993', 'Board Game', 'Tomcat System', '1-8', 'Top-down', 'Board Game / Strategy.', 'Buy properties and bankrupt your rivals to win.', 'The Famicom version featuring Japanese text and locations.', 'This version localized the board for the Japanese market, maintaining the addictive property-trading mechanics of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa', 'NES', 'Monopoly (USA)', '1991', 'Board Game', 'Sculptured Software', '1-8', 'Top-down', 'Board Game / Strategy.', 'Buy properties and bankrupt your rivals to win.', 'The classic Atlantic City edition of Monopoly for the NES.', 'Featuring smooth animations and a challenging AI, it captures the spirit of the board game perfectly with an easy-to-use 8-bit interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-in-my-pocket-europe', 'NES', 'Monster in My Pocket (Europe)', '1992', 'Platform/Action', 'Konami', '1-2', 'Side-scrolling', 'Side-scrolling action.', 'Stop Warlock and his army of miniature monsters.', 'A high-quality Konami platformer based on the toy line.', 'Players control a Vampire or Monster, fighting through "giant-sized" household environments. It''s famous for its tight controls and great soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-in-my-pocket-usa', 'NES', 'Monster in My Pocket (USA)', '1992', 'Platform/Action', 'Konami', '1-2', 'Side-scrolling', 'Side-scrolling action.', 'Stop Warlock and his army of miniature monsters.', 'A high-quality Konami platformer based on the toy line.', 'Players control a Vampire or Monster, fighting through "giant-sized" household environments. It''s famous for its tight controls and great soundtrack.');
