INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motocross-champion-japan', 'NES', 'Motocross Champion (Japan)', '1989', 'Racing', 'Varie', '1', 'Side-scrolling', 'Racing', 'Win motocross events', 'A motorcycle racing game', 'Motocross Champion focuses on competitive racing across dirt tracks.');
