INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mouryou-senki-madara-japan', 'NES', 'Mouryou Senki Madara (Japan)', '1990', 'RPG', 'Konami', '1', 'Top-down', 'Action RPG', 'Defeat supernatural enemies', 'A dark fantasy RPG', 'Mouryou Senki Madara combines action combat with RPG progression in a grim setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mouryou-senki-madara-japan-en-by-aeon-genesis-v10', 'NES', 'Mouryou Senki Madara (Japan) [En by Aeon Genesis v1.0]', '1990', 'RPG', 'Konami', '1', 'Top-down', 'Action RPG', 'Defeat supernatural enemies', 'English-translated RPG', 'This English version of Madara delivers its story-heavy action RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-gimmick-europe', 'NES', 'Mr. Gimmick (Europe)', '1993', 'Platform', 'Sunsoft', '1', 'Side-scrolling', 'Side-scrolling action.', 'Rescue your owner from a toy world using star magic.', 'A late-era technical masterpiece by Sunsoft.', 'Featuring advanced physics and one of the best soundtracks on the NES, players use a star that bounces and acts as both a weapon and a platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man---cleaner-map-graphics', 'NES', 'Ms. Pac-Man - Cleaner Map Graphics', '2010', 'Maze', 'Fan-made', '1-2', 'Single-screen', 'Maze / Arcade.', 'Eat all dots while avoiding ghosts with improved art.', 'A graphical hack that polishes the tile-sets of the classic.', 'This version cleans up the maze borders and fruit icons to provide a more modern and crisp visual experience on the 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man---original-title-screen', 'NES', 'Ms. Pac-Man - Original Title Screen', '2010', 'Maze', 'Fan-made', '1-2', 'Single-screen', 'Maze / Arcade.', 'Clear the mazes in this arcade-accurate version.', 'A hack that restores the original arcade title screen.', 'It replaces the modified NES title screens with the authentic arcade layout, catering to purists who want the 1982 experience at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man---turbo', 'NES', 'Ms. Pac-Man - Turbo', '2010', 'Maze', 'Fan-made', '1-2', 'Single-screen', 'Maze / Arcade.', 'Clear mazes at high speed to test your reflexes.', 'A "Turbo" hack that increases movement speed significantly.', 'Perfect for veterans, this version ramps up the velocity of both Ms. Pac-Man and the ghosts, turning the game into a frantic test of skill.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa', 'NES', 'Ms. Pac-Man (USA)', '1993', 'Maze', 'Namco', '1-2', 'Single-screen', 'Maze / Arcade.', 'Navigate four different mazes and outsmart the ghosts.', 'The official Namco/Tengen release for North America.', 'Featuring different maze layouts than the original Pac-Man and moving fruit bonuses, it''s often considered superior to its predecessor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa-unl', 'NES', 'Ms. Pac-Man (USA) (Unl)', '1990', 'Maze', 'Tengen', '1-2', 'Single-screen', 'Maze / Arcade.', 'Navigate mazes in the unlicensed black cartridge version.', 'The Tengen unlicensed release of the arcade classic.', 'While identical in gameplay to the licensed one, this version was sold outside Nintendo’s approval during the legal battles between Atari and Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa-hack-by-dave-augusta+googie-v10-~mr-pac-man', 'NES', 'Ms. Pac-Man (USA) [Hack by Dave Augusta+Googie v1.0] (~Mr. Pac-Man)', '2010', 'Maze', 'Fan-made', '1-2', 'Single-screen', 'Maze / Arcade.', 'Play as a male version of Pac-Man in the sequel''s mazes.', 'A character swap hack for Ms. Pac-Man.', 'It replaces the female protagonist with the original Pac-Man (bow-less) while keeping the improved maze layouts and mechanics of the second game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppet-adventure---chaos-at-the-carnival-usa', 'NES', 'Muppet Adventure - Chaos at the Carnival (USA)', '1990', 'Platform', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Mini-games / Action.', 'Rescue Miss Piggy by winning various carnival games.', 'A collection of Muppet-themed challenges.', 'Players control different Muppets in stages like river rafting, bumper cars, and a funhouse, all aimed at a younger 8-bit audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musashi-no-bouken-japan', 'NES', 'Musashi no Bouken (Japan)', '1990', 'Action/Adventure', 'Taito', '1', 'Top-down', 'Turn-based RPG.', 'Travel ancient Japan as a young monk to defeat evil.', 'A traditional Dragon Quest-style RPG with folklore themes.', 'Known for its charming setting, players level up, buy equipment, and fight mythological Japanese monsters in strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musashi-no-bouken-japan-en-by-gaijin+madhacker-v098-~adventures-of-musashi-the', 'NES', 'Musashi no Bouken (Japan) [En by Gaijin+MadHacker v0.98] (~Adventures of Musashi, The)', '1990', 'Action/Adventure', 'Taito', '1', 'Top-down', 'Turn-based RPG.', 'Defeat the ancient evil with fully translated text.', 'The English fan translation of Musashi no Bouken.', 'This patch is essential for Western players to enjoy the story, item descriptions, and traditional Japanese humor of this hidden RPG gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musashi-no-ken---tadaima-shugyou-chuu-japan', 'NES', 'Musashi no Ken - Tadaima Shugyou Chuu (Japan)', '1990', 'Action', 'Taito', '1', 'Side-scrolling', 'Side-scrolling action.', 'Train in Kendo to win the national championship.', 'An action game based on the famous Kendo manga/anime.', 'It features fast-paced platforming levels where you fight with a bamboo sword, followed by 1v1 Kendo matches against rival students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mutant-virus-the---crisis-in-a-computer-world-usa', 'NES', 'Mutant Virus, The - Crisis in a Computer World (USA)', '1992', 'Action/Adventure', 'American Video Entertainment', '1', 'Top-down', 'Action / Shooter.', 'Disinfect a giant computer system from a viral outbreak.', 'A unique 360-degree shooter with inertia-based movement.', 'Players pilot a probe inside a computer, shooting "virus" cells that multiply in real-time. It''s known for its high difficulty and unique physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-life-my-love---boku-no-yume---watashi-no-negai-japan', 'NES', 'My Life My Love - Boku no Yume - Watashi no Negai (Japan)', '1992', 'Simulation', 'Coconuts Japan', '1', 'Menu-based', 'Life Simulation.', 'Live a full life from birth to old age in a digital world.', 'A fascinating board-game style life simulator.', 'Similar to "The Game of Life," players make choices about education, jobs, and marriage, influencing their character''s stats and ultimate happiness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-quest-usa', 'NES', 'Mystery Quest (USA)', '1987', 'Platform/Adventure', 'Carry Lab', '1', 'Side-scrolling', 'Side-scrolling action.', 'Explore four large castles to find the wizard''s secrets.', 'An exploration-heavy platformer by Taxan.', 'Known for its non-linear design, players must find keys and power-ups to survive surreal environments and defeat guardians in each castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nagagutsu-wo-haita-neko---sekai-isshuu-80-nichi-daibouken-japan', 'NES', 'Nagagutsu wo Haita Neko - Sekai Isshuu 80 Nichi Daibouken (Japan)', '1986', 'Platform/Adventure', 'Toei Animation', '1', 'Side-scrolling', 'Side-scrolling action.', 'Travel around the world in 80 days to win a bet.', 'An adventure based on the Toei Animation mascot.', 'This game features levels set in London, America, and even space, with the protagonist using various vehicles to speed through his global journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakajima-satoru---f-1-hero-japan', 'NES', 'Nakajima Satoru - F-1 Hero (Japan)', '1988', 'Racing', 'Varie', '1', 'Top-down', 'Sports / Racing.', 'Master the Formula 1 circuit with help from Satoru Nakajima.', 'A professional-grade F1 simulation for Famicom.', 'Endorsed by the first full-time Japanese F1 driver, it features realistic car tuning and actual tracks from the world championship circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakajima-satoru---f-1-hero-2-japan', 'NES', 'Nakajima Satoru - F-1 Hero 2 (Japan)', '1991', 'Racing', 'Varie', '1', 'Top-down', 'Sports / Racing.', 'Win the F1 championship with improved car physics.', 'An advanced sequel to the F1 Hero racing series.', 'It features refined graphics and more complex cockpit views, offering one of the most technical racing experiences available on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-to-issho-english-translation', 'NES', 'Nakayoshi to Issho (English Translation)', '1994', 'Educational', 'Video System', '1', 'Side-scrolling', 'Adventure / Sim.', 'Interact with characters from the Nakayoshi manga magazine.', 'An English fan translation of the popular Shoujo crossover.', 'This translation makes the dialogue-heavy missions and social interactions accessible to fans of classic manga like Sailor Moon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-to-issho-japan', 'NES', 'Nakayoshi to Issho (Japan)', '1994', 'Educational', 'Video System', '1', 'Side-scrolling', 'Adventure / Sim.', 'Complete missions in a world filled with Nakayoshi stars.', 'A social simulation game based on the famous girls'' magazine.', 'Players create an avatar and interact with various manga heroines, completing mini-games and fashion-based tasks in a bright 8-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-classic-japan', 'NES', 'Namco Classic (Japan)', '1988', 'Compilation', 'Namco', '1-2', 'Various', 'Sports / Golf.', 'Win the professional golf tour across realistic courses.', 'A polished and well-regarded golf simulation by Namco.', 'It features a balance of arcade accessibility and realistic physics, including wind, club distance, and a variety of terrains to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-classic-ii-japan', 'NES', 'Namco Classic II (Japan)', '1991', 'Compilation', 'Namco', '1-2', 'Various', 'Sports / Golf.', 'Master the links in this expanded golfing sequel.', 'An improved golf sim with better graphics and more courses.', 'This sequel adds more detailed character sprites and refined green-reading mechanics, solidifying Namco''s reputation for quality 8-bit sports games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namcot-mahjong-iii---mahjong-tengoku-japan', 'NES', 'Namcot Mahjong III - Mahjong Tengoku (Japan)', '1991', 'Board Game', 'Namco', '1-4', 'Top-down', 'Mahjong / Strategy.', 'Play Mahjong in a "Heavenly" themed simulation.', 'The third entry in Namcot''s popular Mahjong series.', 'It offers different playstyles and a story mode where you play against celestial beings, focusing on the pure rules of 4-player Mahjong.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nangoku-shirei!!---spy-vs-spy-japan', 'NES', 'Nangoku Shirei!! - Spy Vs Spy (Japan)', '1986', 'Action/Stealth', 'Kemco', '1-2', 'Top-down', 'Action / Puzzle.', 'Sabotage your rival on a tropical island with traps.', 'The Japanese sequel to the original "Spy Vs Spy."', 'Set on an island, players must find hidden items to build a rocket while setting clever traps to delay the rival spy in split-screen co-op.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nantettatte!!-baseball-japan', 'NES', 'Nantettatte!! Baseball (Japan)', '1989', 'Sports', 'Sunsoft', '1-2', 'Side view', 'Sports / Baseball.', 'Win the league in this "modular" baseball game.', 'A unique Sunsoft game that used exchangeable sub-cartridges.', 'The base game could be updated with small "cassettes" that contained new player data, a very innovative concept for the Famicom in 1990.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('napoleon-senki-japan', 'NES', 'Napoleon Senki (Japan)', '1988', 'Strategy', 'Irem', '1', 'Top-down', 'Real-time strategy.', 'Lead Napoleon''s armies to conquer Europe.', 'A rare and ambitious real-time strategy game.', 'Players command large groups of soldiers (infantry, cavalry, artillery) on the battlefield, making tactical decisions to win historical Napoleonic wars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('narc-usa', 'NES', 'NARC (USA)', '1990', 'Action/Shooter', 'Williams', '1-2', 'Side-scrolling', 'Run and gun / Action.', 'Bust drug lords and clear the streets of criminals.', 'A gritty and violent arcade port by Williams.', 'Known for its digitized sprites and mature themes, players use machine guns and rockets to fight through waves of thugs and bizarre bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('navy-blue-japan', 'NES', 'Navy Blue (Japan)', '1989', 'Strategy', 'Square', '1', 'Top-down', 'Strategy / Board Game.', 'Sink the enemy''s fleet in this advanced "Battleship" sim.', 'A naval combat game with RPG elements.', 'Based on the classic board game, it adds specialized ship abilities and a campaign mode where you earn rank and better vessels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-baseball', 'NES', 'NCAA Baseball', '1994', 'Sports', 'Sculptured Software', '1-2', 'Side view', 'Sports / Baseball.', 'Lead a college team to the World Series championship.', 'A baseball sim focusing on the US collegiate league.', 'It features a variety of college teams and a different recruitment/stat system compared to professional MLB-style games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nekketsu-kakutou-densetsu-japan', 'NES', 'Nekketsu Kakutou Densetsu (Japan)', '1992', 'Fighting', 'Technos', '1-2', 'Side view', '2D Fighting / Brawler.', 'Win the martial arts tournament to prove you are the best.', 'A four-player arena fighter starring Kunio-kun.', 'Unlike the side-scrolling games, this is a pure arena brawler where players can team up or fight in a free-for-all with interactive hazards.');
