INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nekketsu-kouha-kunio-kun-japan', 'NES', 'Nekketsu Kouha Kunio Kun (Japan)', '1986', 'Beat ''em up', 'Technos', '1', 'Side-scrolling', 'Beat ''em up', 'Defeat street gangs', 'A classic brawler', 'Nekketsu Kouha Kunio Kun is a side-scrolling beat ''em up focused on street combat and simple, satisfying mechanics.');
